n/// Checks whether two given arrays are equal with respect to an equalty funciton defined on their element.\n///\n/// O(N)\ndef equals[A](this: Array[A], other: Array[A]) { eq: (A, A) => Bool }: Bool = {\n  if (this.size != other.size) false\n  else {\n    var res = true\n    this.foreachIndex { (idx, elem) {label} =>\n      if (not(eq(elem, other.get(idx)))) {\n        res = false\n        label.break()\n      }\n    }\n    res\n  }\n}\n\n/// Map a function `f` over the elements in a given array.\n/// Modifies the array in-place.\n///\n/// O(N)\ndef map[A](arr: Array[A]) { f: A => A }: Unit = {\n  arr.foreachIndex { (idx, elem) =>\n    arr.set(idx, f(arr.get(idx)))\n  }\n}\n\n/// Map a function over elements.\n/// Allocates a new array of the same size.\n///\n/// O(N)\ndef mapped[A, B](arr: Array[A]) { f: A => B }: Array[B] = {\n  val res = unsafeAllocate(arr.size)\n  arr.foreachIndex { (idx, elem) =>\n    res.set(idx, f(arr.get(idx)))\n  }\n  res\n}\n\n/// Reverses an array in-place.\n///\n/// O(N)\ndef reverse[A](arr: Array[A]): Unit = {\n  val size = arr.size()\n  val mid = size / 2\n\n  // Swap elements from start and end, moving towards the middle\n  each(0, mid) { i =>\n    val temp = arr.get(i)\n    val j = size - 1 - i\n    val other = arr.get(j)\n    arr.set(i, other)\n    arr.set(j, temp)\n  }\n}\n/// Creates a new array with elements in reverse order.\n///\n/// O(N)\ndef reversed[A](arr: Array[A]): Array[A] = {\n  val size = arr.size()\n  val result = unsafeAllocate[A](size)\n\n  // Copy elements in reverse order to new array\n  each(0, size) { i =>\n    val value = arr.get(i)\n    result.set(size - 1 - i, value)\n  }\n  result\n}\n\n/// Fold an array using `f`, starting from the left given a starting value.\n///\n/// O(N)\ndef foldLeft[A, B](arr: Array[A], init: B) { f: (B, A) => B }: B = {\n  var acc = init;\n  arr.foreach { x => acc = f(acc, x) };\n  acc\n}\n\n/// Fold an array using `f`, starting from the right given a starting value.\n///\n/// O(N)\ndef foldRight[A, B](arr: Array[A], init: B) { f: (A, B) => B }: B = {\n  var acc = init;\n  arr.reversed.foreach { x => acc = f(x, acc) };\n  acc\n}\n\n/// Filters a given array with respect to a given predicate such that a\n/// new array containing all the elements for which the predicate\n/// holds is allocated.\n///\n/// O(N)\ndef filtered[A](arr: Array[A]) { shouldKeep: A => Bool }: Array[A] = {\n  val res = arr.copy()\n  var idx = 0\n  arr.foreach { x =>\n    if (shouldKeep(x)) {\n      res.set(idx, x)\n      idx = idx + 1\n    }\n  }\n  res.resize(idx)\n}\n\n/// Check if predicate is true for all elements.\n///\n/// O(N)\ndef all[A](arr: Array[A]) { predicate: A => Bool }: Bool = {\n  var result = true\n  arr.foreach { (x) {label} =>\n    if (not(predicate(x))) {\n      result = false\n      label.break()\n    }\n  }\n  result\n}\n\n/// Check if predicate is true for at least one element.\n///\n/// O(N)\ndef any[A](arr: Array[A]) { predicate: A => Bool }: Bool = {\n  not(arr.all { x => not(predicate(x)) })\n}\n\n/// Count elements satisfying the predicate.\n///\n/// O(N)\ndef count[A](arr: Array[A]) { predicate: A => Bool }: Int = {\n  var count = 0\n  arr.foreach { x =>\n    if (predicate(x)) count = count + 1\n  }\n  count\n}\n\n/// Take first n elements.\n/// Returns a new array.\n///\n/// O(N)\ndef take[A](arr: Array[A], n: Int): Array[A] = {\n  val len = min(max(0, n), arr.size)\n  val result = unsafeAllocate[A](len)\n  each(0, len) { i =>\n    result.set(i, arr.get(i))\n  }\n  result\n}\n\n/// Drop first n elements.\n/// Returns a new array.\n///\n/// O(N)\ndef drop[A](arr: Array[A], n: Int): Array[A] = {\n  val start = min(max(0, n), arr.size)\n  val len = arr.size - start\n  val result = unsafeAllocate[A](len)\n  each(0, len) { i =>\n    result.set(i, arr.get(i + start))\n  }\n  result\n}\n\n/// Return a slice from start (inclusive) to end (exclusive).\n/// Returns a new array.\n///\n/// O(N)\ndef sliced[A](arr: Array[A], start: Int, end: Int): Array[A] = {\n  val validStart = min(max(0, start), arr.size)\n  val validEnd = min(max(validStart, end), arr.size)\n  val len = validEnd - validStart\n  val result = unsafeAllocate[A](len)\n  each(0, len) { i =>\n    result.set(i, arr.get(i + validStart))\n  }\n  result\n}\n\n/// Zip two arrays into an array of pairs.\n/// Length is minimum of input lengths.\n///\n/// O(min(N, M))\ndef zipped[A, B](this: Array[A], other: Array[B]): Array[(A, B)] = {\n  val len = min(this.size, other.size)\n  val result = unsafeAllocate[(A, B)](len)\n  each(0, len) { i =>\n    result.set(i, (this.get(i), other.get(i)))\n  }\n  result\n}\n\n/// Combine two arrays using given function.\n/// Length is minimum of input lengths.\n///\n/// O(min(N, M))\ndef zippedWith[A, B, C](this: Array[A], other: Array[B]) { f: (A, B) => C }: Array[C] = {\n  val len = min(this.size, other.size)\n  val result = unsafeAllocate[C](len)\n  each(0, len) { i =>\n    result.set(i, f(this.get(i), other.get(i)))\n  }\n  result\n}\n\n/// Produce a pair of arrays from an array of pairs.\n/// Allocates two new arrays as a result.\n///\n/// O(N)\ndef unzipped[A, B](arr: Array[(A, B)]): (Array[A], Array[B]) = {\n  val arr1 = unsafeAllocate(arr.size)\n  val arr2 = unsafeAllocate(arr.size)\n  arr.foreachIndex { (idx, tpl) =>\n    val (x, y) = tpl\n    arr1.set(idx, x)\n    arr2.set(idx, y)\n  }\n  (arr1, arr2)\n}\n\n/// Partition a given array into two arrays.\n/// The left array contains the elements that satsify the predicate,\n/// the right array contains the elements that do not.\n///\n/// O(N)\ndef partioned[A](arr: Array[A]) { pred: A => Bool }: (Array[A], Array[A]) = {\n  val tcases = arr.copy()\n  val fcases = arr.copy()\n  var tidx = 0\n  var fidx = 0\n  arr.foreach { x =>\n    if (pred(x)) {\n      tcases.set(tidx, x)\n      tidx = tidx + 1\n    } else {\n      fcases.set(fidx, x)\n      fidx = fidx + 1\n    }\n  }\n  (tcases.resize(tidx), fcases.resize(fidx))\n}\n\n/// Get the _first_ index of the last occurance of `elem`, if there is any.\n///\n/// O(N)\ndef indexOf[A](arr: Array[A], toFind: A) { eq: (A, A) => Bool }: Option[Int] = {\n  var found = None[Int]()\n  arr.foreachIndex { (idx, elem) {label} =>\n    if (eq(elem, toFind) && found.isEmpty) {\n      found = Some(idx)\n      label.break()\n    }\n  }\n  found\n}\n\n/// Get the _last_ index of the last occurance of `elem`, if there is any.\n///\n/// O(N)\ndef lastIndexOf[A](arr: Array[A], toFind: A) { eq: (A, A) => Bool }: Option[Int] = {\n  var lastFound = None[Int]()\n  arr.foreachIndex { (idx, elem) =>\n    if (eq(elem, toFind)) {\n      lastFound = Some(idx)\n    }\n  }\n  lastFound\n}\n\n/// Perform binary search to find the index of a given element.\n///\n/// O(log N)\ndef binarySearch[A](arr: Array[A], toFind: A) { ord: (A, A) => Ordering }: Option[Int] = {\n  def binarySearch(lowerIdx: Int, upperIdx: Int): Option[Int] = {\n    if (lowerIdx > upperIdx) None()\n    else {\n      val mid = lowerIdx + (upperIdx - lowerIdx) / 2\n      val current = arr.get(mid)\n      ord(current, toFind) match {\n        case Less() => binarySearch(mid + 1, upperIdx)\n        case Greater() => binarySearch(lowerIdx, mid - 1)\n        case Equal() => Some(mid)\n      }\n    }\n  }\n  binarySearch(0, arr.size - 1)\n}\n\n/// Sort an array in-place using provided comparison function.\n/// Note: `sort` is unstable since it uses QuickSort (unlike `list::sortBy`)\n///\n/// O(N log N) average case\ndef sort[A](arr: Array[A]) { ord: (A, A) => Ordering }: Unit = {\n  def partition(low: Int, high: Int): Int = {\n    val pivot = arr.get(high)\n    var i = low - 1\n\n    each(low, high) { j =>\n      if (ord(arr.get(j), pivot) is Less()) {\n        i = i + 1\n        swap(arr, i, j)\n      }\n    }\n    swap(arr, i + 1, high)\n    i + 1\n  }\n\n  def quickSort(low: Int, high: Int): Unit = {\n    if (low < high) {\n      val par = partition(low, high)\n      quickSort(low, par - 1)\n      quickSort(par + 1, high)\n    }\n  }\n\n  quickSort(0, arr.size - 1)\n}\n\n/// Sort an array using provided comparison function.\n/// A newly allocated sorted array is returned as result, i.e., the sorting is not in-place.\n/// Note: `sorted` is unstable since it uses QuickSort (unlike `list::sortBy`)\n///\n/// O(N log N) average case\ndef sorted[A](arr: Array[A]) { ord: (A, A) => Ordering }: Array[A] = {\n  val res = arr.copy()\n  res.sort { ord }\n  res\n}\n\n// Show Instances\n// --------------\n\n// TODO: These can eventually be replaced if we ever figure out monomorphization on extern types\n\ndef showBuiltin[A](arr: Array[A]) { showA: A => String }: String = {\n  var output = "Array("\n  val lastIndex = arr.size - 1\n\n  arr.foreachIndex { (index, a) =>\n    if (index == lastIndex) output = output ++ showA(a)\n    else output = output ++ showA(a) ++ ", "\n  }\n  output = output ++ ")"\n\n  output\n}\n\ndef showBuiltin(l: Array[Int]): String = showBuiltin(l) { e => show(e) }\ndef showBuiltin(l: Array[Double]): String = showBuiltin(l) { e => show(e) }\ndef showBuiltin(l: Array[Bool]): String = showBuiltin(l) { e => show(e) }\ndef showBuiltin(l: Array[String]): String = showBuiltin(l) { e => e }\n\ndef println(l: Array[Int]): Unit = println(showBuiltin(l))\ndef println(l: Array[Double]): Unit = println(showBuiltin(l))\ndef println(l: Array[Bool]): Unit = println(showBuiltin(l))\ndef println(l: Array[String]): Unit = println(showBuiltin(l))\n\n// Streaming\n// ---------\n\n/// Turns an `array` into a producer of a push stream\n/// by emitting each contained value from 0 to length - 1.\ndef each[T](array: Array[T]): Unit / emit[T] = {\n  val n = array.size\n  def go(i: Int): Unit = {\n    if (i < n) {\n      do emit(array.get(i))\n      go(i + 1)\n    }\n  }\n  go(0)\n}\n\n/// Connects `array` as a producer to a given pull stream `driver` acting as a consumer.\ndef feed[T, R](array: Array[T]) { driver: () => R / next[T] }: R = {\n  var i = 0\n  try {\n    driver()\n  } with next[T] {\n    resume {\n      if (i < array.size) {\n        val c = i\n        i = c + 1\n        array.get(c)\n      } else {\n        do stop()\n      }\n    }\n  }\n}\n\n/// Collects elements emitted by a push stream producer `stream` into a new array,\n/// discarding the result of the producer.\n/// The provided capacity is a hint for the expected number of elements.\n/// It must be strictly larger than zero.\ndef collect[A](capacity: Int) { stream: () => Unit / emit[A] }: Array[A] =\n  returning::collect[A, Unit](capacity){stream}.second\n\n/// Collects elements emitted by a push stream producer `stream` into a new array,\n/// discarding the result of the producer.\ndef collect[A] { stream: () => Unit / emit[A] }: Array[A] =\n  collect[A](4){stream}\n\nnamespace returning {\n\n  /// Collects elements emitted by a push stream producer `stream` into a new array,\n  /// returning the result of the producer as well as the collected array.\n  /// The provided capacity is a hint for the expected number of elements.\n  /// It must be strictly larger than zero.\n  def collect[A, R](capacity: Int) { stream: () => R / emit[A] }: (R, Array[A]) = {\n    var i = 0\n    var a = unsafeAllocate(capacity)\n    try {\n      (stream(), a.resize(i))\n    } with emit[A] { (v) =>\n      if (i >= a.size) { a = a.resize(2 * a.size) }\n      a.set(i, v)\n      i = i + 1\n      resume(())\n    }\n  }\n\n  /// Collects elements emitted by a push stream producer `stream` into a new array,\n  /// returning the result of the producer as well as the collected array.\n  def collect[A, R] { stream: () => R / emit[A] }: (R, Array[A]) =\n    returning::collect[A, R](4){stream}\n\n}\n'),ef("common/seq.effekt",'/// This file implements the [[Seq]] type as a general purpose functional sequence.\n///\n/// Implemented as a 2-3 finger tree, it supports\n/// - prepend and append in amortized O(1),\n/// - concat(m, n) in O(log(min(m, n)))\n/// - first and last in amortized O(1)\n/// - size in amortized O(1)\n///\n/// More information on finger trees:\n///   https://www.staff.city.ac.uk/~ross/papers/FingerTree.pdf\nmodule seq\n\n/// Sequences of elements\n///\n/// They are represented as 2-3 finger trees.\ntype Seq[A] {\n  Empty()\n  Single(value: A)\n  Deep(size: Int, prefix: Digit[A], middle: Tree[A], suffix: Digit[A])\n}\n\n/// Result of splitting a sequence at the front or back.\ntype View[A] {\n  IsEmpty()\n  View(element: A, remainder: Seq[A])\n}\n\n/// Exception[NoSuchElement] is raised when accessing non-existing elements\n/// or splitting empty collections.\nrecord NoSuchElement()\n\n\nrecord IndexOutOfBounds()\n\n\n\n// Implementation\n// ==============\n// Internal implementation note:\n//   we use the following abbreviations:\n//   - s: suffix\n//   - p: prefix\n//   - v: value\n//   - n: node\n//   - m: middle (spine)\n//   - a,b,c,d: elements of a digit in this order\n//\n// we do not abbreviate:\n//   - size\n\n\n// Internal Types\n// --------------\n\n/// Internal grouping of 1-4 elements\n///\n/// It is called digit since Okasaki (1998) calls finger trees "numerical operations".\ntype Digit[A] {\n  One(value: A)\n  Two(first: A, second: A)\n  Three(first: A, second: A, third: A)\n  Four(first: A, second: A, third: A, fourth: A)\n}\n\n/// Internal representation of a 2-3 tree\ntype Node[A] {\n  // These are necessary to avoid polymorphic recursion\n  Leaf2(first: A, second: A)\n  Leaf3(first: A, second: A, third: A)\n  Node2(size: Int, first: Node[A], second: Node[A])\n  Node3(size: Int, first: Node[A], second: Node[A], third: Node[A])\n}\n\n/// Internal duplicate of Seq\n///\n/// splitting into two type parameters is necessary since our MLton backend does\n/// not support mutually recursive data type declarations.\ntype Finger[A, N] {\n  NoFinger()\n  SingleFinger(value: Node[A])\n  DeepFinger(size: Int, prefix: N, middle: Finger[A, N], suffix: N)\n}\n\n/**\n * Internal\n */\ntype Tree[A] = Finger[A, Digit[Node[A]]]\n\n/**\n * Internal\n */\ntype TreeView[A] {\n  TreeIsEmpty()\n  TreeView(element: Node[A], rest: Tree[A])\n}\n\n\n\n// Measure\n// -------\n\ndef size[A](node: Digit[A]): Int = node match {\n  case One(_) => 1\n  case Two(_, _) => 2\n  case Three(_, _, _) => 3\n  case Four(_, _, _, _) => 4\n}\n\ndef size[A](node: Node[A]): Int = node match {\n  case Leaf2(_, _) => 2\n  case Leaf3(_, _, _) => 3\n  case Node2(size, _, _) => size\n  case Node3(size, _, _, _) => size\n}\n\ndef sizeDeep[A](node: Digit[Node[A]]): Int = node match {\n  case One(a) => a.size\n  case Two(a, b) => a.size + b.size\n  case Three(a, b, c) => a.size + b.size + c.size\n  case Four(a, b, c, d) => a.size + b.size + c.size + d.size\n}\n\ndef size[A](tree: Tree[A]): Int = tree match {\n  case NoFinger() => 0\n  case SingleFinger(value) => value.size\n  case DeepFinger(size, _, _, _) => size\n}\n\n/// The size of the given sequence\ndef size[A](seq: Seq[A]): Int = seq match {\n  case Empty() => 0\n  case Single(value) => 1\n  case Deep(size, _, _, _) => size\n}\n\n\n// Internal smart constructors\n// ---------------------------\n\ndef deepFinger[A](prefix: Digit[Node[A]], middle: Tree[A], suffix: Digit[Node[A]]): Tree[A] =\n  DeepFinger(prefix.sizeDeep + middle.size + suffix.sizeDeep, prefix, middle, suffix)\n\ndef deep[A](prefix: Digit[A], middle: Tree[A], suffix: Digit[A]): Seq[A] =\n  Deep(prefix.size + middle.size + suffix.size, prefix, middle, suffix)\n\ndef node2[A](first: Node[A], second: Node[A]): Node[A] =\n  Node2(first.size + second.size, first, second)\n\ndef node3[A](first: Node[A], second: Node[A], third: Node[A]): Node[A] =\n  Node3(first.size + second.size + third.size, first, second, third)\n\n\n// Adding an element to the left\n// -----------------------------\n\ndef consFinger[A](head: Node[A], tail: Tree[A]): Tree[A] = tail match {\n  case NoFinger()                          => SingleFinger(head)\n  case SingleFinger(b)                     => deepFinger(One(head), NoFinger(), One(b))\n  case DeepFinger(_, One(b), m, s)         => deepFinger(Two(head, b), m, s)\n  case DeepFinger(_, Two(b, c), m, s)      => deepFinger(Three(head, b, c), m, s)\n  case DeepFinger(_, Three(b, c, d), m, s) => deepFinger(Four(head, b, c, d), m, s)\n  case DeepFinger(_, Four(b, c, d, e), m, s) =>\n    deepFinger(Two(head, b), consFinger(node3(c, d, e), m), s)\n}\n\ndef cons[A](head: A, tail: Seq[A]): Seq[A] = tail match {\n  case Empty()                            => Single(head)\n  case Single(b)                          => Deep(2, One(head), NoFinger(), One(b))\n  case Deep(size, One(b), m, s)           => Deep(size + 1, Two(head, b), m, s)\n  case Deep(size, Two(b, c), m, s)        => Deep(size + 1, Three(head, b, c), m, s)\n  case Deep(size, Three(b, c, d), m, s)   => Deep(size + 1, Four(head, b, c, d), m, s)\n  case Deep(size, Four(b, c, d, e), m, s) =>\n    Deep(size + 1, Two(head, b), consFinger(Leaf3(c, d, e), m), s)\n}\n\n\n// Adding an element to the right\n// ------------------------------\n\ndef consFingerRight[A](init: Tree[A], last: Node[A]): Tree[A] = init match {\n  case NoFinger()                          => SingleFinger(last)\n  case SingleFinger(b)                     => deepFinger(One(b), NoFinger(), One(last))\n  case DeepFinger(_, p, m, One(b))         => deepFinger(p, m, Two(b, last))\n  case DeepFinger(_, p, m, Two(b, c))      => deepFinger(p, m, Three(b, c, last))\n  case DeepFinger(_, p, m, Three(b, c, d)) => deepFinger(p, m, Four(b, c, d, last))\n  case DeepFinger(_, p, m, Four(b, c, d, e)) =>\n    deepFinger(p, consFingerRight(m, node3(b, c, d)), Two(e, last))\n}\n\ndef consRight[A](init: Seq[A], last: A): Seq[A] = init match {\n  case Empty()                          => Single(last)\n  case Single(b)                        => Deep(2, One(b), NoFinger(), One(last))\n  case Deep(size, p, m, One(b))         => Deep(size + 1, p, m, Two(b, last))\n  case Deep(size, p, m, Two(b, c))      => Deep(size + 1, p, m, Three(b, c, last))\n  case Deep(size, p, m, Three(b, c, d)) => Deep(size + 1, p, m, Four(b, c, d, last))\n  case Deep(size, p, m, Four(b, c, d, e)) =>\n    Deep(size + 1, p, consFingerRight(m, Leaf3(b, c, d)), Two(e, last))\n}\n\n\n// Splitting the sequence on the left\n// ----------------------------------\n\ndef unconsFinger[A](seq: Tree[A]): TreeView[A] = seq match {\n  case NoFinger()      => TreeIsEmpty()\n  case SingleFinger(v) => TreeView(v, NoFinger())\n  // TODO this is a tail-call-modulo-context\n  case DeepFinger(size, One(a), m, s) => TreeView(a, unconsFinger(m) match {\n    case TreeIsEmpty() => s.toTree\n    case TreeView(b, m2) => DeepFinger(size - a.size, b.toDigitNode, m2, s)\n  })\n  case DeepFinger(size, Two(a, b), m, s)        => TreeView(a, DeepFinger(size - a.size, One(b), m, s))\n  case DeepFinger(size, Three(a, b, c), m, s)   => TreeView(a, DeepFinger(size - a.size, Two(b, c), m, s))\n  case DeepFinger(size, Four(a, b, c, d), m, s) => TreeView(a, DeepFinger(size - a.size, Three(b, c, d), m, s))\n}\n\n// this could be called "uncons", "first", "front", "head", "popFront", "start", "popStart"\ndef uncons[A](seq: Seq[A]): View[A] = seq match {\n  case Empty()   => IsEmpty()\n  case Single(v) => View(v, Empty())\n  case Deep(size, One(a), m, s) => View(a, unconsFinger(m) match {\n    case TreeIsEmpty() => s.toSeq\n    case TreeView(b, m2) => Deep(size - 1, b.toDigit, m2, s)\n  })\n  case Deep(size, Two(a, b), m, s) => View(a, Deep(size - 1, One(b), m, s))\n  case Deep(size, Three(a, b, c), m, s) => View(a, Deep(size - 1, Two(b, c), m, s))\n  case Deep(size, Four(a, b, c, d), m, s) => View(a, Deep(size - 1, Three(b, c, d), m, s))\n}\n\ndef head[A](seq: Seq[A]): A / Exception[NoSuchElement] = seq.uncons match {\n  case IsEmpty() => raise(NoSuchElement(), "Calling `head` on empty sequence.")\n  case View(element, _) => element\n}\n\ndef tail[A](seq: Seq[A]): Seq[A] / Exception[NoSuchElement] = seq.uncons match {\n  case IsEmpty() => raise(NoSuchElement(), "Calling `tail` on empty sequence.")\n  case View(element, rest) => rest\n}\n\n\n// Splitting the sequence on the right\n// -----------------------------------\n\ndef unconsRightFinger[A](seq: Tree[A]): TreeView[A] = seq match {\n  case NoFinger()      => TreeIsEmpty()\n  case SingleFinger(v) => TreeView(v, NoFinger())\n  // TODO this is a tail-call-modulo-context\n  case DeepFinger(size, p, m, One(a)) => TreeView(a, unconsRightFinger(m) match {\n    case TreeIsEmpty() => p.toTree\n    case TreeView(b, m2) => DeepFinger(size - a.size, p, m2, b.toDigitNode)\n  })\n  case DeepFinger(size, p, m, Two(a, b))        => TreeView(b, DeepFinger(size - b.size, p, m, One(a)))\n  case DeepFinger(size, p, m, Three(a, b, c))   => TreeView(c, DeepFinger(size - c.size, p, m, Two(a, b)))\n  case DeepFinger(size, p, m, Four(a, b, c, d)) => TreeView(d, DeepFinger(size - d.size, p, m, Three(a, b, c)))\n}\n\n// this could be called "uncons", "first", "front", "head", "popFront", "start", "popStart"\ndef unconsRight[A](seq: Seq[A]): View[A] = seq match {\n  case Empty()   => IsEmpty()\n  case Single(v) => View(v, Empty())\n  case Deep(size, p, m, One(a)) => View(a, unconsFinger(m) match {\n    case TreeIsEmpty() => p.toSeq\n    case TreeView(b, m2) => Deep(size - 1, p, m2, b.toDigit)\n  })\n  case Deep(size, p, m, Two(a, b))        => View(b, Deep(size - 1, p, m, One(a)))\n  case Deep(size, p, m, Three(a, b, c))   => View(c, Deep(size - 1, p, m, Two(a, b)))\n  case Deep(size, p, m, Four(a, b, c, d)) => View(d, Deep(size - 1, p, m, Three(a, b, c)))\n}\n\n\n// Concatenating Sequences\n// -----------------------\n\ndef concatTree[A](first: Tree[A], middle: List[Node[A]], second: Tree[A]): Tree[A] = {\n\n  // can we get rid of the list?\n\n  def prepend(nodes: List[Node[A]], tree: Tree[A]): Tree[A] = nodes match {\n    case Nil() => tree\n    case Cons(head, tail) => consFinger(head, prepend(tail, tree))\n  }\n\n  def append(tree: Tree[A], nodes: List[Node[A]]): Tree[A] = nodes match {\n    case Nil() => tree\n    case Cons(head, tail) => append(consFingerRight(tree, head), tail)\n  }\n\n  def consFinger(digit: Digit[Node[A]], tree: Tree[A]): Tree[A] = digit match {\n    case One(a) => consFinger(a, tree)\n    case Two(a, b) => consFinger(a, consFinger(b, tree))\n    case Three(a, b, c) => consFinger(a, consFinger(b, consFinger(c, tree)))\n    case Four(a, b, c, d) => consFinger(a, consFinger(b, consFinger(c, consFinger(d, tree))))\n  }\n\n  def toList(digit: Digit[Node[A]]): List[Node[A]] = digit match {\n    case One(a) => Cons(a, Nil())\n    case Two(a, b) => Cons(a, Cons(b, Nil()))\n    case Three(a, b, c) => Cons(a, Cons(b, Cons(c, Nil())))\n    case Four(a, b, c, d) => Cons(a, Cons(b, Cons(c, Cons(d, Nil()))))\n  }\n\n  def rebalance(nodes: List[Node[A]]): List[Node[A]] = nodes match {\n    case Cons(a, Cons(b, Nil())) => Cons(node2(a, b), Nil())\n    case Cons(a, Cons(b, Cons(c, Nil()))) => Cons(node3(a, b, c), Nil())\n    case Cons(a, Cons(b, Cons(c, Cons(d, Nil())))) => Cons(node2(a, b), Cons(node2(c, d), Nil()))\n    case Cons(a, Cons(b, Cons(c, rest))) => Cons(node3(a, b, c), rebalance(rest))\n    case _ => <>\n  }\n\n  def go(prefix: Tree[A], middle: List[Node[A]], suffix: Tree[A]): Tree[A] =\n    (prefix, suffix) match {\n      case (NoFinger(), s)      => prepend(middle, s)\n      case (p, NoFinger())      => append(p, middle)\n      case (SingleFinger(v), s) => consFinger(v, prepend(middle, s))\n      case (p, SingleFinger(v)) => consFingerRight(append(p, middle), v)\n      case (DeepFinger(size1, p1, m1, s1), DeepFinger(size2, p2, m2, s2)) =>\n        val list = s1.toList.append(middle).append(p2.toList)\n        DeepFinger(size1 + size2, p1, go(m1, rebalance(list), m2), s2)\n    }\n\n  go(first, middle, second)\n}\n\ndef concat[A](first: Seq[A], second: Seq[A]): Seq[A] = {\n  def rebalance(t: List[A]): List[Node[A]] = t match {\n    case Cons(a, Cons(b, Nil())) => Cons(Leaf2(a, b), Nil())\n    case Cons(a, Cons(b, Cons(c, Nil()))) => Cons(Leaf3(a, b, c), Nil())\n    case Cons(a, Cons(b, Cons(c, Cons(d, Nil())))) => Cons(Leaf2(a, b), Cons(Leaf2(c, d), Nil()))\n    case Cons(a, Cons(b, Cons(c, rest))) => Cons(Leaf3(a, b, c), rebalance(rest))\n    case _ => <>\n  }\n\n  (first, second) match {\n    case (Empty(), other) => other\n    case (other, Empty()) => other\n    case (Single(v), other) => cons(v, other)\n    case (other, Single(v)) => consRight(other, v)\n    case (Deep(size1, p1, m1, s1), Deep(size2, p2, m2, s2)) =>\n      Deep(size1 + size2, p1, concatTree(m1, rebalance(s1.toList.append(p2.toList)), m2), s2)\n  }\n}\n\n\n// Predicates\n// ----------\n\ndef isEmpty[A](seq: Seq[A]): Bool = seq match {\n  case Empty() => true\n  case _ => false\n}\n\ndef nonEmpty[A](seq: Seq[A]): Bool = seq match {\n  case Empty() => false\n  case _ => true\n}\n\ndef reverse[A](seq: Seq[A]): Seq[A] = {\n\n  // invariant for all internal functions: element is in the sequence\n\n  // this is tail-recursive-modulo-context\n  def go(node: Node[A]): Node[A] = node match {\n    case Leaf2(a, b) => Leaf2(b, a)\n    case Leaf3(a, b, c) => Leaf3(c, b, a)\n    case Node2(size, a, b) => Node2(size, go(b), go(a))\n    case Node3(size, a, b, c) => Node3(size, go(c), go(b), go(a))\n  }\n  def go(digit: Digit[A]): Digit[A] = digit match {\n    case One(a) => One(a)\n    case Two(a, b) => Two(b, a)\n    case Three(a, b, c) => Three(c, b, a)\n    case Four(a, b, c, d) => Four(d, c, b, a)\n  }\n  def go(digits: Digit[Node[A]]): Digit[Node[A]] = digits match {\n    case One(a) => One(go(a))\n    case Two(a, b) => Two(go(b), go(a))\n    case Three(a, b, c) => Three(go(c), go(b), go(a))\n    case Four(a, b, c, d) => Four(go(d), go(c), go(b), go(a))\n  }\n  def go(tree: Tree[A]): Tree[A] = tree match {\n    case NoFinger() => NoFinger()\n    case SingleFinger(value) => SingleFinger(go(value))\n    case DeepFinger(size, p, m, s) => DeepFinger(size, go(s), go(m), go(p))\n  }\n\n  seq match {\n    case Empty() => Empty()\n    case Single(value) => Single(value)\n    case Deep(size, p, m, s) => Deep(size, go(s), go(m), go(p))\n  }\n}\n\n\n/// Random access\ndef index[A](seq: Seq[A], index: Int): A / Exception[NoSuchElement] = {\n\n  // invariant for all internal functions: element is in the sequence\n\n  def go(node: Node[A], index: Int): A = node match {\n    case Leaf2(a, b) => if (index == 0) a else b\n    case Leaf3(a, b, c) => if (index == 0) a else if (index == 1) b else c\n    case Node2(_, a, b) =>\n      val asize = a.size\n      if (index < asize) go(a, index) else go(b, index - asize)\n    case Node3(_, a, b, c) =>\n      val asize = a.size\n      if (index < asize) go(a, index) else {\n        val bsize = asize + b.size\n        if (index < bsize) go(b, index - asize) else go(c, index - bsize)\n      }\n  }\n  def go(digit: Digit[A], index: Int): A = digit match {\n    case One(a) => a\n    case Two(a, b) => if (index == 0) a else b\n    case Three(a, b, c) => if (index == 0) a else if (index == 1) b else c\n    case Four(a, b, c, d) => if (index == 0) a else if (index == 1) b else if (index == 2) c else d\n  }\n  def go(digits: Digit[Node[A]], index: Int): A = digits match {\n    case One(a) => go(a, index)\n    case Two(a, b) =>\n      val asize = a.size\n      if (index < asize) go(a, index) else go(b, index - asize)\n    case Three(a, b, c) =>\n      val asize = a.size\n      if (index < asize) go(a, index) else {\n        val bsize = asize + b.size\n        if (index < bsize) go(b, index - asize) else {\n          go(c, index - bsize)\n        }\n      }\n    case Four(a, b, c, d) =>\n      val asize = a.size\n      if (index < asize) go(a, index) else {\n        val bsize = asize + b.size\n        if (index < bsize) go(b, index - asize) else {\n          val csize = bsize + c.size\n          if (index < csize) go(c, index - bsize) else {\n            go(d, index - csize)\n          }\n        }\n      }\n  }\n  def go(tree: Tree[A], index: Int): A = tree match {\n    case NoFinger() => <{ "Cannot happen!" }>\n    case SingleFinger(value) => go(value, index)\n    case DeepFinger(_, p, m, s) =>\n      val psize = p.sizeDeep\n      if (index < psize) { go(p, index) } else {\n        val msize = psize + m.size\n        if (index < msize) { go(m, index - psize) }\n        else { go(s, index - msize) }\n      }\n  }\n\n  if (index >= seq.size) raise(NoSuchElement(), "...")\n  else seq match {\n    case Empty() => <{ "Cannot happen!" }>\n    case Single(v) => v // has to be the right one due to the check above\n    case Deep(_, p, m, s) =>\n      val psize = p.size\n      if (index < psize) { go(p, index) } else {\n        val msize = psize + m.size\n        if (index < msize) { go(m, index - psize) }\n        else { go(s, index - msize) }\n      }\n  }\n}\n\n/// Random access\ndef update[A](seq: Seq[A], index: Int, value: A): Seq[A] / Exception[NoSuchElement] = {\n\n  // invariant for all internal functions: element is in the sequence\n\n  // this is tail-recursive-modulo-context\n  def go(node: Node[A], index: Int): Node[A] = node match {\n    case Leaf2(a, b) => if (index == 0) Leaf2(value, b) else Leaf2(a, value)\n    case Leaf3(a, b, c) => if (index == 0) Leaf3(value, b, c) else if (index == 1) Leaf3(a, value, c) else Leaf3(a, b, value)\n    case Node2(size, a, b) =>\n      val asize = a.size\n      if (index < asize) Node2(size, go(a, index), b) else Node2(size, a, go(b, index - asize))\n    case Node3(size, a, b, c) =>\n      val asize = a.size\n      if (index < asize) Node3(size, go(a, index), b, c) else {\n        val bsize = asize + b.size\n        if (index < bsize) Node3(size, a, go(b, index - asize), c) else Node3(size, a, b, go(c, index - bsize))\n      }\n  }\n  def go(digit: Digit[A], index: Int): Digit[A] = digit match {\n    case One(a) => One(value)\n    case Two(a, b) => if (index == 0) Two(value, b) else Two(a, value)\n    case Three(a, b, c) => if (index == 0) Three(value, b, c) else if (index == 1) Three(a, value, c) else Three(a, b, value)\n    case Four(a, b, c, d) => if (index == 0) Four(value, b, c, d) else if (index == 1) Four(a, value, c, d) else if (index == 2) Four(a, b, value, d) else Four(a, b, c, value)\n  }\n  def go(digits: Digit[Node[A]], index: Int): Digit[Node[A]] = digits match {\n    case One(a) => One(go(a, index))\n    case Two(a, b) =>\n      val asize = a.size\n      if (index < asize) Two(go(a, index), b) else Two(a, go(b, index - asize))\n    case Three(a, b, c) =>\n      val asize = a.size\n      if (index < asize) Three(go(a, index), b, c) else {\n        val bsize = asize + b.size\n        if (index < bsize) Three(a, go(b, index - asize), c) else {\n          Three(a, b, go(c, index - bsize))\n        }\n      }\n    case Four(a, b, c, d) =>\n      val asize = a.size\n      if (index < asize) Four(go(a, index), b, c, d) else {\n        val bsize = asize + b.size\n        if (index < bsize) Four(a, go(b, index - asize), c, d) else {\n          val csize = bsize + c.size\n          if (index < csize) Four(a, b, go(c, index - bsize), d) else {\n            Four(a, b, c, go(d, index - csize))\n          }\n        }\n      }\n  }\n  def go(tree: Tree[A], index: Int): Tree[A] = tree match {\n    case NoFinger() => <{ "Cannot happen!" }>\n    case SingleFinger(value) => SingleFinger(go(value, index))\n    case DeepFinger(size, p, m, s) =>\n      val psize = p.sizeDeep\n      if (index < psize) { DeepFinger(size, go(p, index), m, s) } else {\n        val msize = psize + m.size\n        if (index < msize) { DeepFinger(size, p, go(m, index - psize), s) }\n        else { DeepFinger(size, p, m, go(s, index - msize)) }\n      }\n  }\n\n  if (index >= seq.size) raise(NoSuchElement(), "...")\n  else seq match {\n    case Empty() => <{ "Cannot happen!" }>\n    case Single(_) => Single(value) // has to be the right one due to the check above\n    case Deep(size, p, m, s) =>\n      val psize = p.size\n      if (index < psize) { Deep(size, go(p, index), m, s) } else {\n        val msize = psize + m.size\n        if (index < msize) { Deep(size, p, go(m, index - psize), s) }\n        else { Deep(size, p, m, go(s, index - msize)) }\n      }\n  }\n}\n\n\ndef each[A](seq: Seq[A]) { consume: (A) => Unit }: Unit = {\n\n  def go(digit: Digit[A]): Unit = digit match {\n    case One(a) => consume(a)\n    case Two(a, b) => consume(a); consume(b)\n    case Three(a, b, c) => consume(a); consume(b); consume(c)\n    case Four(a, b, c, d) => consume(a); consume(b); consume(c); consume(d)\n  }\n\n  def go(node: Node[A]): Unit = node match {\n    case Leaf2(a, b) => consume(a); consume(b)\n    case Leaf3(a, b, c) => consume(a); consume(b); consume(c)\n    case Node2(_, a, b) => go(a); go(b)\n    case Node3(_, a, b, c) => go(a); go(b); go(c)\n  }\n\n  def go(digit: Digit[Node[A]]): Unit = digit match {\n    case One(a) => go(a)\n    case Two(a, b) => go(a); go(b)\n    case Three(a, b, c) => go(a); go(b); go(c)\n    case Four(a, b, c, d) => go(a); go(b); go(c); go(d)\n  }\n\n  def go(tree: Tree[A]): Unit = tree match {\n    case NoFinger() => ()\n    case SingleFinger(v) => go(v)\n    case DeepFinger(_, p, m, s) => go(p); go(m); go(s)\n  }\n\n  seq match {\n    case Empty() => ()\n    case Single(v) => consume(v)\n    case Deep(_, p, m, s) => go(p); go(m); go(s)\n  }\n}\n\ndef each[A](seq: Seq[A]) { f: (A) {Label} => Unit }: Unit = try {\n  seq.each { (el) =>\n    try { f(el) {inner} } with inner: Label {\n      def break() = outer.break()\n      def continue() = ()\n    }\n  }\n} with outer: Label {\n  def break() = ()\n  def continue() = ()\n}\n\ndef eachReverse[A](seq: Seq[A]) { consume: A => Unit }: Unit = {\n\n  def go(digit: Digit[A]): Unit = digit match {\n    case One(a) => consume(a)\n    case Two(a, b) => consume(b); consume(a)\n    case Three(a, b, c) => consume(c); consume(b); consume(a)\n    case Four(a, b, c, d) => consume(d); consume(c); consume(b); consume(a)\n  }\n\n  def go(node: Node[A]): Unit = node match {\n    case Leaf2(a, b) => consume(b); consume(a)\n    case Leaf3(a, b, c) => consume(c); consume(b); consume(a)\n    case Node2(_, a, b) => go(b); go(a)\n    case Node3(_, a, b, c) => go(c); go(b); go(a)\n  }\n\n  def go(digit: Digit[Node[A]]): Unit = digit match {\n    case One(a) => go(a)\n    case Two(a, b) => go(b); go(a)\n    case Three(a, b, c) => go(c); go(b); go(a)\n    case Four(a, b, c, d) => go(d); go(c); go(b); go(a)\n  }\n\n  def go(tree: Tree[A]): Unit = tree match {\n    case NoFinger() => ()\n    case SingleFinger(v) => go(v)\n    case DeepFinger(_, p, m, s) => go(s); go(m); go(p)\n  }\n\n  seq match {\n    case Empty() => ()\n    case Single(v) => consume(v)\n    case Deep(_, p, m, s) => go(s); go(m); go(p)\n  }\n}\n\ndef eachReverse[A](seq: Seq[A]) { f: (A) {Label} => Unit }: Unit = try {\n  seq.eachReverse { (el) =>\n    try { f(el) {inner} } with inner: Label {\n      def break() = outer.break()\n      def continue() = ()\n    }\n  }\n} with outer: Label {\n  def break() = ()\n  def continue() = ()\n}\n\ndef toList[A](seq: Seq[A]): List[A] = {\n  var list: List[A] = Nil()\n  seq.eachReverse { el => list = Cons(el, list) }\n  list\n}\n\ndef toSeq[A](l: List[A]): Seq[A] = {\n  def go(l: List[A], acc: Seq[A]): Seq[A] = l match {\n    case Nil() => acc\n    case Cons(head, tail) => go(tail, consRight(acc, head))\n  }\n  go(l, Empty())\n}\n\n\nrecord Split[A, R](prefix: R, element: A, suffix: R)\n\ndef splitAt[A](seq: Seq[A], index: Int): (Seq[A], Seq[A]) / Exception[IndexOutOfBounds] = {\n\n  // invariant index is in digit\n  def go(digit: Digit[A], index: Int): Split[A, List[A]] = digit match {\n    case One(a) => Split([], a, [])\n    case Two(a, b) => if (index == 0) Split([], a, [b]) else Split([a], b, [])\n    case Three(a, b, c) =>\n      if (index == 0) Split([], a, [b, c])\n      else if (index == 1) Split([a], b, [c])\n      else Split([a, b], c, [])\n    case Four(a, b, c, d) =>\n      if (index == 0) Split([], a, [b, c, d])\n      else if (index == 1) Split([a], b, [c, d])\n      else if (index == 2) Split([a, b], c, [d])\n      else  Split([a, b, c], d, [])\n  }\n\n  def go(digit: Digit[Node[A]], index: Int): Split[Node[A], List[Node[A]]] = digit match {\n    case One(a) => Split([], a, [])\n    case Two(a, b) =>\n      val asize = a.size\n      if (index < asize) Split([], a, [b]) else Split([a], b, [])\n    case Three(a, b, c) =>\n      val asize = a.size\n      if (index < asize) Split([], a, [b, c])\n      else {\n        val bsize = asize + b.size\n        if (index < bsize) Split([a], b, [c])\n        else Split([a, b], c, [])\n      }\n    case Four(a, b, c, d) =>\n      val asize = a.size\n      if (index < asize) Split([], a, [b, c, d])\n      else {\n        val bsize = asize + b.size\n        if (index < bsize) Split([a], b, [c, d])\n        else {\n          val csize = bsize + c.size\n          if (index < csize) Split([a, b], c, [d])\n          else Split([a, b, c], d, [])\n        }\n      }\n  }\n\n  def left(p: List[Node[A]], m: Tree[A], s: Digit[Node[A]]): Tree[A] = p match {\n    case Nil() => m.unconsFinger match {\n      case TreeIsEmpty() => s.toTree\n      case TreeView(a, m2) => deepFinger(a.toDigitNode, m2, s)\n    }\n    case _ => deepFinger(p.toDigitNode, m, s)\n  }\n\n  def left(p: List[A], m: Tree[A], s: Digit[A]): Seq[A] = p match {\n    case Nil() => m.unconsFinger match {\n      case TreeIsEmpty() => s.toSeq\n      case TreeView(a, m2) => deep(a.toDigit, m2, s)\n    }\n    case _ => deep(p.toDigitNode, m, s)\n  }\n  def right(p: Digit[A], m: Tree[A], s: List[A]): Seq[A] = s match {\n    case Nil() => m.unconsRightFinger match {\n      case TreeIsEmpty() => p.toSeq\n      case TreeView(a, m2) => deep(p, m2, a.toDigit)\n    }\n    case _ => deep(p, m, s.toDigitNode)\n  }\n\n\n  def right(p: Digit[Node[A]], m: Tree[A], s: List[Node[A]]): Tree[A] = s match {\n    case Nil() => m.unconsRightFinger match {\n      case TreeIsEmpty() => p.toTree\n      case TreeView(a, m2) => deepFinger(p, m2, a.toDigitNode)\n    }\n    case _ => deepFinger(p, m, s.toDigitNode)\n  }\n\n  def go(tree: Tree[A], index: Int): Split[Node[A], Tree[A]] = tree match {\n    case NoFinger() => println("Cannot happen!"); <{ "Cannot happen!" }>\n    case SingleFinger(value) => Split(NoFinger(), value, NoFinger())\n    case DeepFinger(size, p, m, s) =>\n      val psize = p.sizeDeep;\n      // It is in the prefix\n      if (index < psize) {\n        val Split(pp, v, ps) = go(p, index);\n        Split(pp.toTree, v, left(ps, m, s))\n      } else {\n        val msize = psize + m.size\n        // It is somewhere in the spine\n        if (index < msize) {\n          val Split(mp, v, ms) = go(m, index - psize);\n          val mpsize = psize + mp.size;\n          val Split(vp, w, vs) = go(v.toDigitNode, index - mpsize);\n          Split(right(p, mp, vp), w, left(vs, ms, s))\n        // It is somewhere in the suffix\n        } else {\n          val Split(sp, v, ss) = go(s, index - msize)\n          Split(right(p, m, sp), v, ss.toTree)\n        }\n      }\n  }\n\n  if (index < 0) {\n    do raise(IndexOutOfBounds(), "...")\n  } else if (index >= seq.size) {\n    (seq, Empty())\n  } else seq match {\n    case Empty() => (Empty(), Empty())\n    case Single(v) => (Empty(), seq)\n    case Deep(size, p, m, s) =>\n      val psize = p.size;\n      // It is in the prefix\n      if (index < psize) {\n        val Split(pp, v, ps) = go(p, index);\n        (toSeq(pp), left(Cons(v, ps), m, s))\n      } else {\n        val msize = psize + m.size\n        // It is somewhere in the spine\n        if (index < msize) {\n          val Split(mp, v, ms) = go(m, index - psize);\n          val mpsize = psize + mp.size;\n          val Split(vp, w, vs) = go(v.toDigit, index - mpsize);\n          (right(p, mp, vp), left(Cons(w, vs), ms, s))\n        // It is somewhere in the suffix\n        } else {\n          val Split(sp, v, ss) = go(s, index - msize);\n          (right(p, m, sp), Cons(v, ss).toSeq)\n        }\n      }\n  }\n}\n\n\ndef insert[A](seq: Seq[A], value: A, index: Int): Seq[A] / Exception[IndexOutOfBounds] =\n  splitAt(seq, index) match {\n    case (prefix, suffix) => prefix.concat(cons(value, suffix))\n  }\n\n\n\n// Internal conversions\n// --------------------\n\ndef toTree[A](digit: Digit[Node[A]]): Tree[A] = digit match {\n  case One(a) => SingleFinger(a)\n  case Two(a, b) => deepFinger(One(a), NoFinger(), One(b))\n  case Three(a, b, c) => deepFinger(Two(a, b), NoFinger(), One(c))\n  case Four(a, b, c, d) => deepFinger(Three(a, b, c), NoFinger(), One(d))\n}\n\ndef toTree[A](digit: List[Node[A]]): Tree[A] = digit match {\n  case Nil() => NoFinger()\n  case Cons(a, Nil()) => SingleFinger(a)\n  case Cons(a, Cons(b, Nil())) => deepFinger(One(a), NoFinger(), One(b))\n  case Cons(a, Cons(b, Cons(c, Nil()))) => deepFinger(Two(a, b), NoFinger(), One(c))\n  case Cons(a, Cons(b, Cons(c, Cons(d, Nil())))) => deepFinger(Three(a, b, c), NoFinger(), One(d))\n  case _ => <>\n}\n\ndef toSeq[A](d: Digit[A]): Seq[A] =  d match {\n  case One(a) => Single(a)\n  case Two(a, b) => Deep(2, One(a), NoFinger(), One(b))\n  case Three(a, b, c) => Deep(3, Two(a, b), NoFinger(), One(c))\n  case Four(a, b, c, d) => Deep(4, Three(a, b, c), NoFinger(), One(d))\n}\n\ndef toDigitNode[A](n: Node[A]): Digit[Node[A]] = n match {\n  case Node2(_, a, b) => Two(a, b)\n  case Node3(_, a, b, c) => Three(a, b, c)\n  case _ => <{ "Should not happen" }>\n}\n\ndef toDigitNode[A](n: List[A]): Digit[A] = n match {\n  case Cons(a, Nil()) => One(a)\n  case Cons(a, Cons(b, Nil())) => Two(a, b)\n  case Cons(a, Cons(b, Cons(c, Nil()))) => Three(a, b, c)\n  case Cons(a, Cons(b, Cons(c, Cons(d, Nil())))) => Four(a, b, c, d)\n  case _ => <{ "Should not happen" }>\n}\n\ndef toDigit[A](n: Node[A]): Digit[A] = n match {\n  case Leaf2(a, b) => Two(a, b)\n  case Leaf3(a, b, c) => Three(a, b, c)\n  case _ => <{ "Should not happen" }>\n}\n\ndef toList[A](digit: Digit[A]): List[A] = digit match {\n  case One(a) => Cons(a, Nil())\n  case Two(a, b) => Cons(a, Cons(b, Nil()))\n  case Three(a, b, c) => Cons(a, Cons(b, Cons(c, Nil())))\n  case Four(a, b, c, d) => Cons(a, Cons(b, Cons(c, Cons(d, Nil()))))\n}\n\ndef map[A, B](seq: Seq[A]) { f: A => B }: Seq[B] = {\n  var result: Seq[B] = Empty()\n  seq.each { a => result = result.consRight(f(a)) }\n  result\n}\n\ndef map[A, B](seq: Seq[A]) { f: (A) {Label} => B }: Seq[B] = {\n  var result: Seq[B] = Empty()\n  seq.each { (a) {label} => result = result.consRight(f(a) {label}) }\n  result\n}\n\n\n// TODO iterator interface\n//\n\n// interface Iterator[A] {\n//   def value(): Option[A]\n//   def next(): Unit\n// }\n\n// interface Generator[A] {\n//   def yield(value: A): Unit\n// }\n\n// def iterate[A, R](seq: Seq[A]) { prog: {Iterator[A]} => R }: R = {\n\n//   var k: Unit => Unit at {} = box { () => () }\n//   var v: Option[A] = None()\n\n//   try { seq.each { el => do yield(el) } } with Generator[A] {\n//     def yield(value) = { v = Some(value); k = box resume }\n//   }\n\n//   new Iterator[A] {\n//     def value() = v\n//     def next() = (unbox k)(())\n//   }\n// }\n\n\n// TODO equality comparison\n//\n'),ef("common/map.effekt",'module map\n\nimport stream\n\n/// Ordered finite immutable map, backed by balanced binary trees of logarithmic depth.\nrecord Map[K, V](tree: internal::Tree[K, V], compare: (K, K) => Ordering at {})\n\n/// Create a new empty map using a pure, first-class comparison function.\n///\n/// O(1)\ndef empty[K, V](compare: (K, K) => Ordering at {}): Map[K, V] =\n  Map(internal::empty(), compare)\n\n/// Create a new empty map using a generic comparison function.\n/// Only available on JavaScript backends!\n///\n/// O(1)\ndef emptyGeneric[K, V](): Map[K, V] =\n  Map(\n    internal::empty(),\n    box { (left: K, right: K) => genericCompare(left, right) }\n  )\n\n/// Check if map `m` is empty.\n///\n/// O(1)\ndef isEmpty[K, V](m: Map[K, V]): Bool = internal::isEmpty(m.tree)\n\n/// Check if map `m` is nonempty.\n///\n/// O(1)\ndef nonEmpty[K, V](m: Map[K, V]): Bool = internal::nonEmpty(m.tree)\n\n/// Create a new map containing the mapping from `k` to `v` and a pure, first-class comparison function.\n///\n/// O(1)\ndef singleton[K, V](k: K, v: V, compare: (K, K) => Ordering at {}): Map[K, V] =\n  Map(internal::singleton(k, v), compare)\n\n/// Create a new map containing the mapping from `k` to `v` using a generic comparison function.\n/// Only available on the JavaScript backends!\n///\n/// O(1)\ndef singletonGeneric[K, V](k: K, v: V): Map[K, V] =\n  Map(\n    internal::singleton(k, v),\n    box { (left: K, right: K) => genericCompare(left, right) }\n  )\n\n/// Get the size of the map (the number of keys/values).\n///\n/// O(1)\ndef size[K, V](m: Map[K, V]): Int = internal::size(m.tree)\n\n/// Insert a new key `k` and value `v` into the map `m`.\n/// If the key `k` is already present in `m`, its associated value is replaced with `v`.\n///\n/// O(log N)\ndef put[K, V](m: Map[K, V], k: K, v: V): Map[K, V] = {\n  val newTree = internal::put(m.tree, m.compare, k, v)\n  Map(newTree, m.compare)\n}\n\n/// Insert a new key `k` and value `v` into the map `m`.\n/// If the key `k` is already present in `m` with value `v2`, the function `combine` is called on `k`, `v`, `v2`.\n///\n/// O(log N)\ndef putWithKey[K, V](m: Map[K, V], k: K, v: V) { combine: (K, V, V) => V }: Map[K, V] = {\n  val newTree = internal::putWithKey(m.tree, m.compare, k, v) {combine}\n  Map(newTree, m.compare)\n}\n\n/// Lookup the value at a key `k` in the map `m`.\n///\n/// O(log N)\ndef get[K, V](m: Map[K, V], k: K): Option[V] = internal::get(m.tree, m.compare, k)\n\n/// Lookup the value at a key `k` in the map `m`.\n/// If there is no key, use the `default` block to retrieve a default value.\n///\n/// O(log N)\ndef getOrElse[K, V](m: Map[K, V], k: K) { default: => V }: V =\n  internal::get(m.tree, m.compare, k) match {\n    case None() => default()\n    case Some(v) => v\n  }\n\n/// Check if map `m` contains a key `k`.\n///\n/// O(log N)\ndef contains[K, V](m: Map[K, V], k: K): Bool =\n  internal::get(m.tree, m.compare, k) match {\n    case None() => false\n    case Some(v) => true\n  }\n\n/// Get minimum in the map `m`.\n///\n/// O(log N)\ndef getMin[K, V](m: Map[K, V]): Option[(K, V)] = internal::getMin(m.tree)\n\n/// Get maximum in the map `m`.\n///\n/// O(log N)\ndef getMax[K, V](m: Map[K, V]): Option[(K, V)] = internal::getMax(m.tree)\n\n/// Tree a function `f` over values in map `m`.\n///\n/// O(N)\ndef map[K, V1, V2](m: Map[K, V1]) { f: (K, V1) => V2 }: Map[K, V2] = {\n  val newTree = internal::map(m.tree) {f}\n  Map(newTree, m.compare)\n}\n\n/// Tree a function `f` over values in map `m`.\n///\n/// O(N)\ndef map[K, V1, V2](m: Map[K, V1]) { f: V1 => V2 }: Map[K, V2] = {\n  m.map { (_k, v) => f(v) }\n}\n\n/// Tree a function `f` over values in map `m`, keeping only the values where `f` returns `Some(...)`\n///\n/// O(N)\ndef mapMaybe[K, V1, V2](m: Map[K, V1]) { f: (K, V1) => Option[V2] }: Map[K, V2] = {\n  val newTree = internal::mapMaybe(m.tree) {f}\n  Map(newTree, m.compare)\n}\n\n/// Filters a map `m` with a `shouldKeep` function,\n/// keeping only the elements where `shouldKeep` returns `true`.\n///\n/// Law: `m.filter { f } === m.mapMaybe { (k, v) => if (f(k, v)) Some(v) else None() }`\n///\n/// O(N)\ndef filter[K, V](m: Map[K, V]) { shouldKeep: (K, V) => Bool }: Map[K, V] = {\n  val newTree = internal::filter(m.tree) {shouldKeep}\n  Map(newTree, m.compare)\n}\n\n/// Filters a map `m` with a `shouldKeep` function,\n/// keeping only the values where `shouldKeep` returns `true`.\n///\n/// O(N)\ndef filter[K, V](m: Map[K, V]) { shouldKeep: V => Bool }: Map[K, V] =\n  m.filter { (_k, v) => shouldKeep(v) }\n\n/// Traverse all keys and their associated values in map `m` in order,\n/// running the function `action` on a key and its associated value.\n///\n/// Law: `m.foreach { action } === m.toList.foreach { action }`\n///\n/// O(N)\n///\n/// TODO: Support {Control} for early exits.\ndef foreach[K, V](m: Map[K, V]) { action: (K, V) => Unit }: Unit =\n  internal::foreach(m.tree) {action}\n\n/// Convert a map `m` into a list of (key, value) pairs.\n///\n/// O(N)\ndef toList[K, V](m: Map[K, V]): List[(K, V)] = {\n  var acc = Nil()\n  m.foreach { (k, v) =>\n    acc = Cons((k, v), acc)\n  }\n  acc.reverse\n}\n\n/// Get a list of keys of the map `m`.\n///\n/// O(N)\ndef keys[K, V](m: Map[K, V]): List[K] = {\n  var acc = Nil()\n  m.foreach { (k, _v) =>\n    acc = Cons(k, acc)\n  }\n  acc.reverse\n}\n\n/// Get a list of values of the map `m`.\n///\n/// O(N)\ndef values[K, V](m: Map[K, V]): List[V] = {\n  var acc = Nil()\n  m.foreach { (_k, v) =>\n    acc = Cons(v, acc)\n  }\n  acc.reverse\n}\n\n/// Create a map from a list of (key, value) pairs and a pure, first-class comparison function.\n/// If the list contains more than one value for the same key,\n/// only the last value is used in the map.\n///\n/// O(N) if the list is sorted by key,\n/// O(N log N) otherwise\ndef fromList[K, V](pairs: List[(K, V)], compare: (K, K) => Ordering at {}): Map[K, V] =\n  Map(internal::fromList(pairs, compare), compare)\n\n/// Create a map from a list of (key, value) pairs and a generic comparison function.\n/// If the list contains more than one value for the same key,\n/// only the last value is used in the map.\n/// Works only on JavaScript backends!\n///\n/// O(N) if the list is sorted by key,\n/// O(N log N) otherwise\ndef fromListGeneric[K, V](pairs: List[(K, V)]): Map[K, V] = {\n  val compare: (K, K) => Ordering at {} = box { (left, right) => genericCompare(left, right) }\n  Map(internal::fromList(pairs, compare), compare)\n}\n\n/// Remove a key `k` from a map `m`.\n/// If `k` is not in `m`, `m` is returned.\n///\n/// O(log N)\ndef delete[K, V](m: Map[K, V], k: K): Map[K, V] = {\n  val newTree = internal::delete(m.tree, m.compare, k)\n  Map(newTree, m.compare)\n}\n\n/// Can be used to insert, delete, or update a value.\n/// Law: `get(m.alter(k){f}, k) === f(get(m, k))`\n///\n/// O(log N)\ndef alter[K, V](m: Map[K, V], k: K) { f: Option[V] => Option[V] }: Map[K, V] = {\n  val newTree = internal::alter(m.tree, m.compare, k) {f}\n  Map(newTree, m.compare)\n}\n\n/// Update or delete a value associated with key `k` in map `m`.\n///\n/// O(log N)\ndef update[K, V](m: Map[K, V], k: K) { f: (K, V) => Option[V] }: Map[K, V] = {\n  val newTree = internal::update(m.tree, m.compare, k) {f}\n  Map(newTree, m.compare)\n}\n\n/// Update or delete a value associated with key `k` in map `m`.\n///\n/// O(log N)\ndef update[K, V](m: Map[K, V], k: K) { f: V => Option[V] }: Map[K, V] =\n  m.update(k) { (_k, v) => f(v) }\n\n/// Get `n`-th (key, value) pair in the map `m`.\n///\n/// O(log N)\ndef getIndex[K, V](m: Map[K, V], n: Int): Option[(K, V)] =\n  internal::getIndex(m.tree, n)\n\n/// Construct a new map which contains all elements of `m1`\n/// except those where the key is found in `m2`.\n/// Uses an explicit pure, first-class comparison function.\n///\n/// O(???)\ndef difference[K, V](m1: Map[K, V], m2: Map[K, V], compare: (K, K) => Ordering at {}) = {\n  val newTree = internal::difference(m1.tree, m2.tree, compare)\n  Map(newTree, compare)\n}\n\n/// Construct a new map which contains all elements of `m1`\n/// except those where the key is found in `m2`.\n/// Uses the comparison function from `m1`.\n///\n/// O(???)\ndef difference[K, V](m1: Map[K, V], m2: Map[K, V]) = {\n  val newTree = internal::difference(m1.tree, m2.tree, m1.compare)\n  Map(newTree, m1.compare)\n}\n\n/// Construct a new map which contains the elements of both `m1` and `m2`.\n/// When a key is associated with a value in both `m1` and `m2`, the new value is determined using the `combine` function.\n/// Uses an explicit pure, first-class comparison function.\n///\n/// O(???)\ndef union[K, V](m1: Map[K, V], m2: Map[K, V], compare: (K, K) => Ordering at {}) { combine: (K, V, V) => V }: Map[K, V] = {\n  val newTree = internal::union(m1.tree, m2.tree, compare) {combine}\n  Map(newTree, compare)\n}\n\n/// Construct a new map which contains the elements of both `m1` and `m2`.\n/// When a key is associated with a value in both `m1` and `m2`, the new value is determined using the `combine` function.\n/// Uses an explicit pure, first-class comparison function.\n///\n/// O(???)\ndef union[K, V](m1: Map[K, V], m2: Map[K, V], compare: (K, K) => Ordering at {}) { combine: (V, V) => V }: Map[K, V] =\n  union(m1, m2, compare) { (k, v1, v2) => combine(v1, v2) }\n\n/// Construct a new map which contains the elements of both `m1` and `m2`.\n/// Left-biased: Uses values from `m1` if there are duplicate keys and\n/// uses the comparison function from `m1`.\n///\n/// O(???)\ndef union[K, V](m1: Map[K, V], m2: Map[K, V]): Map[K, V] =\n  union[K, V](m1, m2, m1.compare) { (k, v1, v2) => v1 }\n\n/// Construct a new map which combines all elements that are in both `m1` and `m2` using the `combine` function.\n///\n/// O(???)\ndef intersection[K, A, B, C](m1: Map[K, A], m2: Map[K, B], compare: (K, K) => Ordering at {}) { combine: (K, A, B) => C }: Map[K, C] = {\n  val newTree = internal::intersection(m1.tree, m2.tree, compare) {combine}\n  Map(newTree, compare)\n}\n\n/// Construct a new map which combines all elements that are in both `m1` and `m2` using the `combine` function.\n///\n/// O(???)\ndef intersection[K, A, B, C](m1: Map[K, A], m2: Map[K, B], compare: (K, K) => Ordering at {}) { combine: (A, B) => C }: Map[K, C] =\n  m1.intersection[K, A, B, C](m2, compare) { (k, v1, v2) => combine(v1, v2) }\n\n/// Construct a new map which combines all elements that are in both `m1` and `m2`.\n/// Left-biased: Always uses values from `m1` and the comparison function from `m1`.\n///\n/// O(???)\ndef intersection[K, A, B](m1: Map[K, A], m2: Map[K, B]): Map[K, A] =\n  m1.intersection[K, A, B, A](m2, m1.compare) { (k, v1, v2) => v1 }\n\n/// Please don\'t directly use:\n/// - the `Tree` type\n/// - its internal constructors `Bin` & `Tip`,\n/// - and these functions.\n/// As they might change down the line and are not considered stable / public.\nnamespace internal {\n  /// Balanced binary trees of logarithmic depth.\n  type Tree[K, V] {\n    Bin(size: Int, k: K, v: V, left: Tree[K, V], right: Tree[K, V]);\n    Tip()\n  }\n\n  /// Create a new empty tree.\n  ///\n  /// O(1)\n  def empty[K, V](): Tree[K, V] = Tip()\n\n  /// Check if tree `m` is empty.\n  ///\n  /// O(1)\n  def isEmpty[K, V](m: Tree[K, V]): Bool =\n    m match {\n      case Tip() => true\n      case _     => false\n    }\n\n  /// Check if tree `m` is nonempty.\n  ///\n  /// O(1)\n  def nonEmpty[K, V](m: Tree[K, V]): Bool =\n    m match {\n      case Tip() => false\n      case _     => true\n    }\n\n  /// Create a new tree containing only the mapping from `k` to `v`.\n  ///\n  /// O(1)\n  def singleton[K, V](k: K, v: V): Tree[K, V] =\n    Bin(1, k, v, Tip(), Tip())\n\n  /// Get the size of the tree (the number of keys/values).\n  ///\n  /// O(1)\n  def size[K, V](m: Tree[K, V]): Int =\n    m match {\n      case Tip() => 0\n      case Bin(size, _, _, _, _) => size\n    }\n\n  /// Insert a new key `k` and value `v` into the tree `m`.\n  /// If the key `k` is already present in `m`, its associated value is replaced with `v`.\n  ///\n  /// O(log N)\n  def put[K, V](m: Tree[K, V], compare: (K, K) => Ordering at {}, k: K, v: V): Tree[K, V] =\n    m match {\n      case Tip() => singleton(k, v)\n      case Bin(size, k2, v2, l, r) =>\n        compare(k, k2) match {\n          case Less() => balance(k2, v2, put(l, compare, k, v), r)\n          case Greater() => balance(k2, v2, l, put(r, compare, k, v))\n          case Equal() => Bin(size, k, v, l, r)\n        }\n    }\n\n  /// Insert a new key `k` and value `v` into the tree `m`.\n  /// If the key `k` is already present in `m` with value `v2`, the function `combine` is called on `k`, `v`, `v2`.\n  ///\n  /// O(log N)\n  def putWithKey[K, V](m: Tree[K, V], compare: (K, K) => Ordering at {}, k: K, v: V) { combine: (K, V, V) => V } : Tree[K, V] =\n    m match {\n      case Tip() => singleton(k, v)\n      case Bin(size, k2, v2, l, r) =>\n        compare(k, k2) match {\n          case Less() => balance(k2, v2, l.putWithKey(compare, k, v){combine}, r)\n          case Greater() => balance(k2, v2, l, r.putWithKey(compare, k, v){combine})\n          case Equal() => Bin(size, k, combine(k, v, v2), l, r)\n        }\n    }\n\n  /// Lookup the value at a key `k` in the tree `m`.\n  ///\n  /// O(log N)\n  def get[K, V](m: Tree[K, V], compare: (K, K) => Ordering at {}, k: K): Option[V] =\n    m match {\n      case Tip() => None()\n      case Bin(size, k2, v, l, r) =>\n        compare(k, k2) match {\n          case Less() => get(l, compare, k)\n          case Greater() => get(r, compare, k)\n          case Equal() => Some(v)\n        }\n    }\n\n  /// Get minimum in the tree `m`.\n  ///\n  /// O(log N)\n  def getMin[K, V](m: Tree[K, V]): Option[(K, V)] = {\n    def go(k: K, v: V, m: Tree[K, V]): (K, V) = {\n      m match {\n        case Tip() => (k, v)\n        case Bin(_, k2, v2, l, _) => go(k2, v2, l)\n      }\n    }\n\n    m match {\n      case Tip() => None()\n      case Bin(_, k, v, l, _) => Some(go(k, v, l))\n    }\n  }\n\n  /// Get maximum in the tree `m`.\n  ///\n  /// O(log N)\n  def getMax[K, V](m: Tree[K, V]): Option[(K, V)] = {\n    def go(k: K, v: V, m: Tree[K, V]): (K, V) = {\n      m match {\n        case Tip() => (k, v)\n        case Bin(_, k2, v2, _, r) => go(k2, v2, r)\n      }\n    }\n\n    m match {\n      case Tip() => None()\n      case Bin(_, k, v, _, r) => Some(go(k, v, r))\n    }\n  }\n\n  /// Forgets the values of a tree, setting them all to `(): Unit`.\n  /// Used by `set`s internally.\n  ///\n  /// Law: `m.forget === m.map { (_k, _v) => () }`\n  ///\n  /// O(N)\n  def forget[K, V](m: Tree[K, V]): Tree[K, Unit] =\n    m match {\n      case Tip() => Tip()\n      case Bin(size, k, v, l, r) =>\n        Bin(size, k, (), l.forget, r.forget)\n    }\n\n  /// Tree a function `f` over values in tree `m`.\n  ///\n  /// O(N)\n  def map[K, V1, V2](m: Tree[K, V1]) { f : (K, V1) => V2 }: Tree[K, V2] =\n    m match {\n      case Tip() => Tip()\n      case Bin(size, k, v, l, r) =>\n        Bin(size, k, f(k, v), l.map {f}, r.map {f})\n    }\n\n  /// Tree a function `f` over values in tree `m`, keeping only the values where `f` returns `Some(...)`\n  ///\n  /// O(N)\n  def mapMaybe[K, V1, V2](m: Tree[K, V1]) { f : (K, V1) => Option[V2] }: Tree[K, V2] =\n    m match {\n      case Tip() => Tip()\n      case Bin(size, k, v, l, r) => f(k, v) match {\n        case Some(v2) => link(k, v2, l.mapMaybe {f}, r.mapMaybe {f})\n        case None() => link2(l.mapMaybe {f}, r.mapMaybe {f})\n      }\n    }\n\n  /// Filters a tree `m` with a `shouldKeep` function,\n  /// keeping only the elements where `shouldKeep` returns `true`.\n  ///\n  /// Law: `m.filter { f } === m.mapMaybe { (k, v) => if (f(k, v)) Some(v) else None() }`\n  ///\n  /// O(N)\n  def filter[K, V](m: Tree[K, V]) { shouldKeep: (K, V) => Bool }: Tree[K, V] = {\n    def go(tree: Tree[K, V]): (Tree[K, V], Bool) = tree match {\n      case Tip() => (Tip(), false)\n      case Bin(size, k, v, l, r) =>\n        val (l2, lchanged) = go(l)\n        val (r2, rchanged) = go(r)\n        if (shouldKeep(k, v)) {\n          val changed = lchanged || rchanged\n          val tree2 = if (changed) {\n            link(k, v, l2, r2)\n          } else {\n            tree\n          }\n          (tree2, changed)\n        } else {\n          (link2(l2, r2), true)\n        }\n    }\n\n    go(m).first\n  }\n\n  /// Traverse all keys and their associated values in tree `m` in order,\n  /// running the function `action` on a key and its associated value.\n  ///\n  /// Law: `m.foreach { action } === m.toList.foreach { action }`\n  ///\n  /// O(N)\n  ///\n  /// TODO: Support {Control} for early exits.\n  def foreach[K, V](m: Tree[K, V]) { action: (K, V) => Unit }: Unit = {\n    def go(m: Tree[K, V]): Unit = {\n      m match {\n        case Tip() => ()\n        case Bin(_, k, v, l, r) =>\n          go(l)\n          action(k, v)\n          go(r)\n      }\n    }\n    go(m)\n  }\n\n  /// Create a tree from a list of (key, value) pairs.\n  /// If the list contains more than one value for the same key,\n  /// only the last value is used in the tree.\n  ///\n  /// O(N) if the list is sorted by key,\n  /// O(N log N) otherwise\n  def fromList[K, V](pairs: List[(K, V)], compare: (K, K) => Ordering at {}): Tree[K, V] = {\n    pairs match {\n      case Nil() => Tip()\n      case Cons((k, v), Nil()) => singleton(k, v)\n      case Cons((k, v), rest) =>\n        // TODO: this function should really, **really** get inlined!\n        def notOrdered(k: K, pairs: List[(K, V)]) = {\n          pairs match {\n            case Nil() => false\n            case Cons((k2, _), _) =>  // k >= k2\n              compare(k, k2) match {\n                case Less() => false\n                case Greater() => true\n                case Equal() => true\n              }\n          }\n        }\n\n        // Naive insertion, used for the worst-case scenario when the list is not sorted by key\n        def insertMany(m: Tree[K, V], pairs: List[(K, V)]) = {\n          var treeSoFar = m\n          pairs.foreach { case (k, v) =>\n            treeSoFar = treeSoFar.put(compare, k, v)\n          }\n          treeSoFar\n        }\n\n        // Returns a triple `(tree, xs, ys)`\n        //\n        // Invariant: At least one of `xs`, `ys` is empty.\n        // Moreover, if `ys` is nonempty, its keys are **not** ordered!\n        // Otherwise, all of the seen keys have been ordered so far.\n        //\n        // TODO: Possibly use a better type to encode the invariant?\n        def create(level: Int, pairs: List[(K, V)]): (Tree[K, V], List[(K, V)], List[(K, V)]) = {\n          pairs match {\n            case Nil() => (Tip(), [], [])\n            case Cons((k, v), rest) =>\n              if (level == 1) {\n                val singleton = Bin(1, k, v, Tip(), Tip())\n                if (notOrdered(k, rest)) {\n                  (singleton, [], rest)\n                } else {\n                  (singleton, rest, [])\n                }\n              } else {\n                val res = create(level.bitwiseShr(1), pairs)\n                res match {\n                  case (_, Nil(), _) => res\n                  case (l, Cons((k2, v2), Nil()), zs) => (l.putMax(k2, v2), [], zs)\n                  case (l, Cons((k2, v2), rest2), _) =>\n                    val xs = Cons((k2, v2), rest2) // @-pattern\n\n                    if (notOrdered(k2, rest2)) { (l, [], xs) }\n                    else {\n                      val (r, zs, ws) = create(level.bitwiseShr(1), rest2);\n                      (link(k2, v2, l, r), zs, ws)\n                    }\n                }\n              }\n          }\n        }\n\n        def go(level: Int, m: Tree[K, V], pairs: List[(K, V)]): Tree[K, V] = {\n          pairs match {\n            case Nil() => m\n            case Cons((k, v), Nil()) => m.putMax(k, v)\n            case Cons((k, v), rest) =>\n              if (notOrdered(k, rest)) { insertMany(m, pairs) }\n              else {\n                val l = m; // m is the left subtree here\n                val cr = create(level, rest)\n                cr match {\n                  case (r, xs, Nil()) => go(level.bitwiseShl(1), link(k, v, l, r), xs)\n                  case (r, Nil(), ys) => insertMany(link(k, v, l, r), ys)\n                  case _ => panic("create: go: cannot happen, invariant broken!")\n                }\n              }\n          }\n        }\n\n        if (notOrdered(k, rest)) { insertMany(singleton(k, v), rest) }\n        else { go(1, singleton(k, v), rest) }\n    }\n  }\n\n  /// Remove a key `k` from a tree `m`.\n  /// If `k` is not in `m`, `m` is returned.\n  ///\n  /// O(log N)\n  def delete[K, V](m: Tree[K, V], compare: (K, K) => Ordering at {}, k: K): Tree[K, V] =\n    m match {\n      case Tip() => Tip()\n      case Bin(_, k2, v2, l, r) =>\n        compare(k, k2) match {\n          case Less() => balance(k2, v2, l.delete(compare, k), r)\n          case Greater() => balance(k2, v2, l, r.delete(compare, k))\n          case Equal() => glue(l, r)\n        }\n    }\n\n  /// Can be used to insert, delete, or update a value.\n  /// Law: `get(m.alter(k){f}, k) === f(get(m, k))`\n  ///\n  /// O(log N)\n  def alter[K, V](m: Tree[K, V], compare: (K, K) => Ordering at {}, k: K) { f: Option[V] => Option[V] }: Tree[K, V] =\n    m match {\n      case Tip() =>\n        f(None()) match {\n          case None() => Tip()\n          case Some(v) => singleton(k, v)\n        }\n      case Bin(size, k2, v2, l, r) =>\n        compare(k, k2) match {\n          case Less() => balance(k2, v2, l.alter(compare, k){f}, r)\n          case Greater() => balance(k2, v2, l, r.alter(compare, k){f})\n          case Equal() =>\n            f(Some(v2)) match {\n              case Some(v) => Bin(size, k2, v, l, r)\n              case None() => glue(l, r)\n            }\n        }\n    }\n\n  /// Update or delete a value associated with key `k` in tree `m`.\n  ///\n  /// O(log N)\n  def update[K, V](m: Tree[K, V], compare: (K, K) => Ordering at {}, k: K) { f: (K, V) => Option[V] }: Tree[K, V] =\n    m match {\n      case Tip() => Tip()\n      case Bin(size, k2, v2, l, r) =>\n        compare(k, k2) match {\n          case Less() => balance(k2, v2, l.update(compare, k){f}, r)\n          case Greater() => balance(k2, v2, l, r.update(compare, k){f})\n          case Equal() =>\n            f(k2, v2) match {\n              case Some(v) => Bin(size, k2, v, l, r)\n              case None() => glue(l, r)\n            }\n        }\n    }\n\n  /// Get `n`-th (key, value) pair in the tree `m`.\n  ///\n  /// O(log N)\n  def getIndex[K, V](m: Tree[K, V], n: Int): Option[(K, V)] =\n    m match {\n      case Tip() => None()\n      case Bin(size, k, v, l, r) =>\n        val sizeL = l.size()\n        compareInt(sizeL, n) match {\n          case Less() => r.getIndex(n - (sizeL + 1))\n          case Greater() => l.getIndex(n)\n          case Equal() => Some((k, v))\n        }\n    }\n\n  /// Construct a new tree which contains all elements of `m1`\n  /// except those where the key is found in `m2`.\n  ///\n  /// O(???)\n  def difference[K, V](m1: Tree[K, V], m2: Tree[K, V], compare: (K, K) => Ordering at {}): Tree[K, V] =\n    (m1, m2) match {\n      case (Tip(), m2) => Tip()\n      case (m1, Tip()) => m1\n      case (m1, Bin(_, k, _, l2, r2)) =>\n        val (l1, _, r1) = m1.splitLookup(compare, k)\n        val leftDiff = l1.difference(l2, compare)\n        val rightDiff = r1.difference(r2, compare)\n        if ((leftDiff.size() + rightDiff.size()) == m1.size()) { m1 }\n        else { link2(leftDiff, rightDiff) }\n    }\n\n  /// Construct a new tree which contains the elements of both `m1` and `m2`.\n  /// When a key is associated with a value in both `m1` and `m2`, the new value is determined using the `combine` function.\n  ///\n  /// O(???)\n  def union[K, V](m1: Tree[K, V], m2: Tree[K, V], compare: (K, K) => Ordering at {}) { combine : (K, V, V) => V }: Tree[K, V] = {\n    // Internal function similar to `putWithKey`, but right-biased. Only used here, recursively.\n    def putWithKeyR(m: Tree[K, V], k: K, v: V): Tree[K, V] = {\n      m match {\n        case Tip() => singleton(k, v)\n        case Bin(size, k2, v2, l, r) =>\n          compare(k, k2) match {\n            case Less() => balance(k2, v2, l.putWithKeyR(k, v), r)\n            case Greater() => balance(k2, v2, l, r.putWithKeyR(k, v))\n            case Equal() => Bin(size, k, combine(k2, v2, v), l, r)\n          }\n      }\n    }\n\n    (m1, m2) match {\n      case (_, Tip()) => m1\n      case (_, Bin(_, k, v, Tip(), Tip())) => m1.putWithKeyR(k, v)\n      case (Bin(_, k, v, Tip(), Tip()), _) => m2.putWithKey(compare, k, v){combine}\n      case (Tip(), _) => m2\n      case (Bin(_, k1, v1, l1, r1), _) =>\n        val (l2, optMid, r2) = m2.splitLookup(compare, k1)\n        val leftUnion = union(l1, l2, compare){combine}\n        val rightUnion = union(r1, r2, compare){combine}\n        optMid match {\n          case None() => link(k1, v1, leftUnion, rightUnion)\n          case Some(v2) => link(k1, combine(k1, v1, v2), leftUnion, rightUnion)\n        }\n    }\n  }\n\n  /// Construct a new tree which combines all elements that are in both `m1` and `m2` using the `combine` function.\n  ///\n  /// O(???)\n  def intersection[K, A, B, C](m1: Tree[K, A], m2: Tree[K, B], compare: (K, K) => Ordering at {}) { combine: (K, A, B) => C }: Tree[K, C] =\n    (m1, m2) match {\n      case (Tip(), _) => Tip()\n      case (_, Tip()) => Tip()\n      case (Bin(_, k, v1, l1, r1), _) =>\n        val (l2, mid, r2) = m2.splitLookup(compare, k)\n        val left = l1.intersection(l2, compare) { combine }\n        val right = r1.intersection(r2, compare) { combine }\n        mid match {\n          case Some(v2) => link(k, combine(k, v1, v2), left, right)\n          case None() => link2(left, right)\n        }\n    }\n\n  // -------------\n  // Internal\n\n  val ratio = 2\n  val delta = 3\n\n  def bin[K, V](k: K, v: V, l: Tree[K, V], r: Tree[K, V]): Tree[K, V] = {\n    Bin(l.size() + r.size() + 1, k, v, l, r)\n  }\n\n  def balance[K, V](k: K, v: V, l: Tree[K, V], r: Tree[K, V]): Tree[K, V] = {\n    /*\n      k1->v1\n      /    \\\n      t1     m                    k2->v2\n            =                   /      \\\n          k2->v2        ~>    k1->v1    t3\n          /   \\               /    \\\n          t2    t3            t1    t2\n    */\n    def singleL[A, B](k1: A, v1: B, t1: Tree[A, B], m: Tree[A, B]): Tree[A, B] = {\n      m match {\n        case Bin(_, k2, v2, t2, t3) => bin(k2, v2, bin(k1, v1, t1, t2), t3)\n        case _ => panic("impossible: singleL: Tip")\n      }\n    }\n\n    /*\n          k1->v1\n          /     \\\n        m      t3            k2->v2\n        =                   /      \\\n      k2->v2        ~>    t1       k1->v1\n        /   \\               /       /   \\\n      t1    t2            t1      t2    t3\n    */\n    def singleR[A, B](k1: A, v1: B, m: Tree[A, B], t3: Tree[A, B]): Tree[A, B] = {\n      m match {\n        case Bin(_, k2, v2, t1, t2) => bin(k2, v2, t1, bin(k1, v1, t2, t3))\n        case _ => panic("impossible: singleR: Tip")\n      }\n    }\n\n    /*\n          k1->v1                     k3->v3\n        /      \\                   /      \\\n      t1        m                k1->v1    k2->v2\n                =                /  \\      /   \\\n              k2->v2     ~>     t1  t2    t3   t4\n              /     \\\n            k3->v3   t4\n            /  \\\n          t2    t3\n    */\n    def doubleL[A, B](k1: A, v1: B, t1: Tree[A, B], m: Tree[A, B]): Tree[A, B] = {\n      m match {\n        case Bin(_, k2, v2, Bin(_, k3, v3, t2, t3), t4) =>\n          bin(k3, v3, bin(k1, v1, t1, t2), bin(k2, v2, t3, t4))\n        case _ => panic("impossible: doubleL: Tip")\n      }\n    }\n\n    /*\n              k1->v1                  k3->v3\n              /      \\                /      \\\n              m      t4            k2->v2    k1->v1\n              =                    /  \\      /   \\\n            k2->v2         ~>     t1  t2    t3   t4\n          /     \\\n        t1      k3->v3\n                  /  \\\n                t2    t3\n    */\n    def doubleR[A, B](k1: A, v1: B, m: Tree[A, B], t4: Tree[A, B]): Tree[A, B] = {\n      m match {\n        case Bin(_, k2, v2, t1, Bin(_, k3, v3, t2, t3)) =>\n          bin(k3, v3, bin(k2, v2, t1, t2), bin(k1, v1, t3, t4))\n        case _ =>\n          panic("impossible: doubleR: Tip")\n      }\n    }\n\n    def rotateL[A, B](k: A, v: B, l: Tree[A, B], r: Tree[A, B]): Tree[A, B] = {\n      r match {\n        case Bin(_, _, _, rl, rr) and (rl.size() < ratio * rr.size()) => singleL(k, v, l, r)\n        case _ => doubleL(k, v, l, r)\n      }\n    }\n    def rotateR[A, B](k: A, v: B, l: Tree[A, B], r: Tree[A, B]): Tree[A, B] = {\n      l match {\n        case Bin(_, _, _, ll, lr) and (lr.size() < ratio * ll.size()) => singleR(k, v, l, r)\n        case _ => doubleR(k, v, l, r)\n      }\n    }\n\n    val sizeL = l.size()\n    val sizeR = r.size()\n    val sizeCombined = sizeL + sizeR + 1\n\n    if ((sizeL + sizeR) <= 1) { Bin(sizeCombined, k, v, l, r) }\n    else if (sizeR > (delta * sizeL)) { rotateL(k, v, l, r) }\n    else if (sizeL > (delta * sizeR)) { rotateR(k, v, l, r) }\n    else { Bin(sizeCombined, k, v, l, r)}\n  }\n\n  record MaxView[K, V](k: K, v: V, m: Tree[K, V])\n  record MinView[K, V](k: K, v: V, m: Tree[K, V])\n\n  def maxViewSure[K, V](k: K, v: V, l: Tree[K, V], r: Tree[K, V]): MaxView[K, V] =\n    (l, r) match {\n      case (l, Tip()) => MaxView(k, v, l)\n      case (l, Bin(_, kr, vr, rl, rr)) =>\n        val MaxView(km, vm, r2) = maxViewSure(kr, vr, rl, rr)\n        MaxView(km, vm, balance(k, v, l, r2))\n    }\n\n  def minViewSure[K, V](k: K, v: V, l: Tree[K, V], r: Tree[K, V]): MinView[K, V] =\n    (l, r) match {\n      case (Tip(), r) => MinView(k, v, r)\n      case (Bin(_, kl, vl, ll, lr), r) =>\n        val MinView(km, vm, l2) = minViewSure(kl, vl, ll, lr)\n        MinView(km, vm, balance(k, v, l2, r))\n    }\n\n  /// Internal: Glues two balanced trees (with respect to each other) together.\n  def glue[K, V](l: Tree[K, V], r: Tree[K, V]): Tree[K, V] =\n    (l, r) match {\n      case (Tip(), r) => r\n      case (l, Tip()) => l\n      case (Bin(sizeL, kl, vl, ll, lr), Bin(sizeR, kr, vr, rl, rr)) =>\n        if (sizeL > sizeR) {\n          val MaxView(km, m, l2) = maxViewSure(kl, vl, ll, lr)\n          balance(km, m, l2, r)\n        } else {\n          val MinView(km, m, r2) = minViewSure(kr, vr, rl, rr)\n          balance(km, m, l, r2)\n        }\n    }\n\n  def splitLookup[K, V](m: Tree[K, V], compare: (K, K) => Ordering at {}, k: K): (Tree[K, V], Option[V], Tree[K, V]) =\n    m match {\n      case Tip() => (Tip(), None(), Tip())\n      case Bin(_, k2, v2, l, r) =>\n        compare(k, k2) match {\n          case Less() =>\n            val (lessThan, mid, greaterThan) = l.splitLookup(compare, k);\n            (lessThan, mid, link(k2, v2, greaterThan, r))\n          case Greater() =>\n            val (lessThan, mid, greaterThan) = r.splitLookup(compare, k);\n            (link(k2, v2, l, lessThan), mid, greaterThan)\n          case Equal() => (l, Some(v2), r)\n        }\n    }\n\n  def link[K, V](k: K, v: V, l: Tree[K, V], r: Tree[K, V]): Tree[K, V] = {\n    (l, r) match {\n      case (Tip(), r) => r.putMin(k, v)\n      case (l, Tip()) => l.putMax(k, v)\n      case (Bin(sizeL, kl, vl, ll, lr), Bin(sizeR, kr, vr, rl, rr)) =>\n        if ((delta * sizeL) < sizeR) { balance(kr, vr, link(k, v, l, rl), rr) }\n        else if ((delta * sizeR) < sizeL) { balance(kl, vl, ll, link(k, v, lr, r)) }\n        else { bin(k, v, l, r) }\n    }\n  }\n\n  /// Internal: merge two trees\n  def link2[K, V](l: Tree[K, V], r: Tree[K, V]): Tree[K, V] =\n    (l, r) match {\n      case (Tip(), r) => r\n      case (l, Tip()) => l\n      case (Bin(sizeL, kl, vl, ll, lr), Bin(sizeR, kr, vr, rl, rr)) =>\n        if ((delta * sizeL) < sizeR) { balance(kr, vr, link2(l, lr), rr) }\n        else if ((delta * sizeR) < sizeL) { balance(kl, vl, ll, link2(lr, r)) }\n        else { glue(l, r) }\n    }\n\n  def putMin[K, V](m: Tree[K, V], k: K, v: V): Tree[K, V] =\n    m match {\n      case Tip() => singleton(k, v)\n      case Bin(_, k2, v2, l, r) =>\n        balance(k2, v2, l.putMin(k, v), r)\n    }\n\n  def putMax[K, V](m: Tree[K, V], k: K, v: V): Tree[K, V] =\n    m match {\n      case Tip() => singleton(k, v)\n      case Bin(_, k2, v2, l, r) =>\n        balance(k2, v2, l, r.putMax(k, v))\n    }\n\n  // Section: for tests and invariants:\n\n  /// Check if a tree `m` is balanced.\n  def isBalanced[K, V](m: Tree[K, V]): Bool =\n    m match {\n      case Tip() => true\n      case Bin(_, _, _, l, r) =>\n        val bothSmall = l.size() + r.size() <= 1\n        val leftSmallEnough = l.size() <= delta * r.size()\n        val rightSmallEnough = r.size() <= delta * l.size()\n        (bothSmall || (leftSmallEnough && rightSmallEnough)) && isBalanced(l) && isBalanced(r)\n    }\n\n  // Section: prettyprinting for trees:\n\n  /// Works only on the backends that support `genericShow` (JavaScript)!\n  def prettyTree[K, V](m: Tree[K, V]): String = {\n    // Helper function to recursively build the string representation of the tree\n    def go(t: Tree[K, V], prefix: String, isTail: Bool): String = {\n      t match {\n        case Tip() => ""\n        case Bin(_, k, v, l, r) =>\n          val pair = k.show ++ " → " ++ v.show\n          val currentLine = prefix ++ (if (isTail) "└── " else "├── ") ++ pair ++ "\\n"\n\n          val newPrefix = prefix ++ (if (isTail) "    " else "│   ")\n          val leftStr = go(l, newPrefix, false)\n          val rightStr = go(r, newPrefix, true)\n\n          currentLine ++ leftStr ++ rightStr\n      }\n    }\n\n    // Start the recursion with the initial tree, an empty prefix, and true for the root being the tail\n    go(m, "", true)\n  }\n\n  def prettyPairs[K, V](list: List[(K, V)]) { showLeft: K => String } { showRight: V => String }: String = {\n    val res: String =\n      list.map { case (k, v) => showLeft(k) ++ " → " ++ showRight(v) }\n          .join(", ")\n\n    "[" ++ res ++ "]"\n  }\n}\n\n\n// Streaming\n// ---------\n\n/// Turns a `map` into a producer of a push stream\n/// of `(key, value)` pairs by emitting each contained *in order*.\ndef each[K, V](map: Map[K, V]): Unit / emit[(K, V)] =\n  map.foreach { (k, v) => do emit((k, v)) }\n\n/// Turns a `map` into a producer of a push stream\n/// of its keys by emitting each contained *in order*.\ndef eachKey[K, V](map: Map[K, V]): Unit / emit[K] =\n  map.foreach { (k, _v) => do emit(k) }\n\n/// Turns a `map` into a producer of a push stream\n/// of its values by emitting each contained.\ndef eachValue[K, V](map: Map[K, V]): Unit / emit[V] =\n  map.foreach { (_k, v) => do emit(v) }\n\n/// Collects `(key, value)` pairs from a push stream producer `stream` into a new `map`\n/// using the provided `compare` function, discarding the result of the producer.\ndef collect[K, V](compare: (K, K) => Ordering at {}) { stream: () => Unit / emit[(K, V)] }: Map[K, V] =\n  returning::collect[K, V, Unit](compare){stream}.second\n\nnamespace returning {\n  /// Collects `(key, value)` pairs from a push stream producer `stream` into a new `map`,\n  /// using the provided `compare` function, returning the result of the producer as well as the collected map.\n  def collect[K, V, R](compare: (K, K) => Ordering at {}) { stream: () => R / emit[(K, V)] }: (R, Map[K, V]) =\n    try {\n      (stream(), empty(compare))\n    } with emit[(K, V)] { case (k, v) =>\n      val (r, map) = resume(());\n      (r, map.put(k, v))\n    }\n}\n'),ef("common/result.effekt",'module result\n\nimport effekt\nimport option\nimport exception\n\n/// Represents the result of a potentially failing computation.\n/// It is the "reification" of the Exception[E] effect.\ntype Result[A, E] {\n  Error(exception: E, msg: String);\n  Success(a: A)\n}\n\n/// Represent ("reify") the result of a potentially failing computation.\ndef result[A, E] { f: => A / Exception[E] }: Result[A, E] = try {\n  Success(f())\n} with Exception[E] {\n  def raise(exc, msg) = Error(exc, msg)\n}\ndef result[A, E](proxy: on[E]) { f: => A / Exception[E] }: Result[A, E] = try {\n  Success(f())\n} with Exception[E] {\n  def raise(exc, msg) = Error(exc, msg)\n}\n\n/// Extracts the value of a result, if available\n/// Monadic "reflection"\ndef value[A, E](r: Result[A, E]): A / Exception[E] = r match {\n  case Success(a) => a\n  case Error(exc, msg) => do raise(exc, msg)\n}\n\n/// Converts a result to an option forgetting the error details\ndef toOption[A, E](r: Result[A, E]): Option[A] = r match {\n  case Success(a) => Some(a)\n  case Error(exc, msg) => None()\n}\n\ndef isError[A, E](r: Result[A, E]): Bool =\n  if (r is Error(_, _)) true else false\n\ndef isSuccess[A, E](r: Result[A, E]): Bool =\n  if (r is Success(_)) true else false'),ef("common/random.effekt",'module random\n\nimport stream\nimport array\nimport option\nimport exception\nimport io/filesystem\nimport io/error\n\n/// Infinite pull stream of random bytes.\neffect random(): Byte\n\n// ---------------------\n// Sources of randomness\n\n/// A streaming source (push stream) of byte-level randomness\n/// based on Park and Miller\'s MINSTD with revised parameters.\n///\n/// Deterministic: needs a 32bit `seed` -- you can use `bench::timestamp`.\ndef minstd(seed: Int): Unit / emit[Byte] = {\n  // Initialize state with seed, ensuring it\'s not zero\n  var state = if (seed == 0) 1 else seed\n\n  def nextInt(): Int = {\n    // Uses only at most 32-bit integers internally\n    // (Schrage\'s method: https://en.wikipedia.org/wiki/Lehmer_random_number_generator#Schrage\'s_method)\n    val a = 48271\n    val m = 2147483647\n\n    val q = m / a           // 44488\n    val r = m.mod(a)        //  3399\n\n    val div = state / q     // max: M / Q = A = 48271\n    val rem = state.mod(q)\t// max: Q - 1     = 44487\n\n    val s = rem * a;        // max: 44487 * 48271 = 2147431977\n    val t = div * r;        // max: 48271 *  3399 =  164073129\n\n    val result = s - t\n    // keep the state positive\n    if (result < 0) result + m else result\n  }\n\n  forever {\n    state = nextInt()\n    val b = state.mod(256).toByte\n    do emit(b)\n  }\n}\n\n/// A thin wrapper over `minstd`, handling a reader of random bytes.\n///\n/// Deterministic: needs a 32bit `seed` -- you can use `bench::timestamp`.\n///\n/// Implementation is similar to `stream::source`, specialized for bytes and the `random` effect.\ndef minstd(seed: Int) { randomnessReader: () => Unit / random }: Unit = {\n  var next = box { 0xFF } // sentinel value\n  next = box {\n    try {\n      minstd(seed)\n      <> // safe: randomness generator cannot run out of numbers...\n    } with emit[Byte] { v =>\n      next = box { resume(()) }\n      v\n    }\n  }\n\n  try randomnessReader() with random {\n    resume(next())\n  }\n}\n\n/// CSPRNG from `/dev/urandom`, handling a reader of random bytes.\n/// Only works on Unix-like OSes!\ndef devurandom { randomnessReader: () => Unit / random }: Unit / Exception[IOError] =\n  try {\n    with readFile("/dev/urandom")\n    try randomnessReader() with random {\n      resume(do next())\n    }\n  } with stop {\n    do raise(io::error::EOF(), "Unexpected EOF when reading /dev/urandom!")\n  }\n\n// ------------------------\n// Functions using `random`\n//\n// Always two variants:\n// - readType(): Type / random\n// - readTypes(): Unit / {emit[Type], random}\n\ndef randomByte(): Byte / random = do random()\ndef randomBytes(): Unit / {emit[Byte], random} =\n  forever { do emit(do random()) }\n\ndef randomBool(): Bool / random = {\n  val b = do random()\n  b.toInt.mod(2) == 1\n}\ndef randomBools(): Unit / {emit[Bool], random} =\n  forever { do emit(randomBool()) }\n\ndef randomInt32(): Int / random = {\n  var result = 0\n  repeat(4) {\n    val b = do random()\n    result = result * 256 + b.toInt\n  }\n  val signBit = result.bitwiseShr(31).bitwiseAnd(1) == 0\n  result.mod(1.bitwiseShl(31)).abs * if (signBit) 1 else -1\n}\ndef randomInt32s(): Unit / {emit[Int], random} =\n  forever { do emit(randomInt32()) }\n\n/// `max` is _inclusive_!\ndef randomInt(min: Int, max: Int): Int / random = {\n  if (min > max) {\n    randomInt(max, min)\n  } else {\n    val range = max - min + 1\n    val bytesNeeded = (log(range.toDouble) / log(256.0)).ceil\n\n    var result = 0\n    repeat(bytesNeeded) {\n      val b = do random()\n      result = result * 256 + b.toInt\n    }\n\n    min + (abs(result).mod(range))\n  }\n}\n\n/// `max` is _inclusive_!\ndef randomInts(min: Int, max: Int): Unit / {emit[Int], random} =\n  forever { do emit(randomInt(min, max)) }\n\n\n/// Random double between 0.0 and 1.0\ndef randomDouble(): Double / random =\n  (randomInt32().toDouble / 1.bitwiseShl(31).toDouble).abs\n  // This is not perfect, but it will do for now.\ndef randomDoubles(): Unit / {emit[Double], random} =\n  forever { do emit(randomDouble()) }\n\n/// Shuffle an array in-place using the Fisher-Yates algorithm.\ndef shuffle[A](arr: Array[A]): Unit / random = {\n  val n = arr.size\n  each(0, n - 1) { i =>\n    arr.swap(i, randomInt(i, n - 1))\n  }\n}\n\n/// Pick a random element from an array.\n///\n/// Panics when called on an empty array.\ndef pick[A](arr: Array[A]): A / random =\n  if (arr.size == 0) {\n    panic("Pick from an empty array")\n  } else {\n    arr.get(randomInt(0, arr.size - 1))\n  }\n\n\nnamespace examples {\ndef main() = {\n    println("prng")\n    prngRandom()\n  }\n\n  def prngRandom(): Unit = {\n    with minstd(1337);\n\n    println("int32s:")\n    repeat(10) {\n      println(randomInt32())\n    }\n\n    println("int32s, part2:")\n    repeat(10) {\n      println(randomInt(0, 2147483647))\n      println(randomInt(-2147483648, 0))\n    }\n\n    println("doubles:")\n    repeat(10) {\n      println(randomDouble().round(3))\n    }\n\n    println("randomInt:")\n    repeat(10) {\n      val a = randomInt(0, 9)\n      val b = randomInt(0, 9)\n      val c = randomInt(0, 9)\n      println(a.show ++ " " ++ b.show ++ " " ++ c.show)\n      println(a * 100 + b * 10 + c)\n    }\n  }\n\n  def unixRandom(): Unit = {\n    with on[IOError].report;\n    with devurandom;\n\n    val a = randomInt32()\n    val b = randomInt32()\n\n    // This is just to use the generated numbers :)\n    println((a.show ++ b.show).length != 0)\n  }\n}'),ef("common/partial.effekt","module partial\n\nimport effekt\nimport option\n\n\neffect fail(): Nothing\n\ndef attempt[R] { program: () => R / fail } { fallback: () => R }: R =\n  try {\n    program()\n  } with fail {\n    fallback()\n  }\n\ndef onFail[R] { fallback: () => R } { program: () => R / fail }: R =\n  try {\n    program()\n  } with fail {\n    fallback()\n  }\n\ndef succeeds { program: () => Unit / fail }: Bool =\n  try { program(); true } with fail { false }\n\ndef optionally[R] { program: () => R / fail }: Option[R] =\n  try {\n    Some(program())\n  } with fail {\n    None()\n  }\n\ndef must[R] { program: () => R / stop }: R / fail =\n  try { program() } with stop { resume(do fail()) }\n\n/// Run `program` forever until `fail` is thrown.\ndef exhaustively { program: () => Unit / fail }: Unit =\n  try {\n    def go(): Unit = {\n      program()\n      go()\n    }\n    go()\n  } with fail {\n    ()\n  }\n\ndef crash[R](message: String) { program: () => R / fail }: R =\n  attempt { program() } { panic(message) }\n\ndef suchThat[A](value: A){ predicate: A => Bool }: Option[A] =\n  if (predicate(value)) { Some(value) } else { None() }\n\ndef getOrFail[A](option: Option[A]): A / fail =\n  option.getOrElse { do fail() }\n\nnamespace returning {\n\ndef exhaustively[R](init: R) { program: () => R / fail }: R =\n  var res = init\n  try {\n    def go(): R = {\n      res = program()\n      go()\n    }\n    go()\n  } with fail {\n    res\n  }\n\n}\n"),ef("common/dequeue.effekt","module dequeue\n\n\n/// An implementation of a functional dequeue, using Okasaki's\n/// bankers dequeue implementation.\n///\n/// Translation from the Haskell implementation:\n///   https://hackage.haskell.org/package/dequeue-0.1.12/docs/src/Data-Dequeue.html#Dequeue\nrecord Dequeue[R](front: List[R], frontSize: Int, rear: List[R], rearSize: Int)\n\ndef emptyQueue[R](): Dequeue[R] = Dequeue(Nil(), 0, Nil(), 0)\n\ndef isEmpty[R](dq: Dequeue[R]): Bool = dq match {\n    case Dequeue(f, fs, r, rs) => (fs == 0) && (rs == 0)\n}\n\ndef size[R](dq: Dequeue[R]): Int = dq match {\n    case Dequeue(f, fs, r, rs) => fs + rs\n}\n\ndef first[R](dq: Dequeue[R]): Option[R] = dq match {\n    case Dequeue(f, fs, r, rs) =>\n      if ((fs == 0) && (rs == 1)) { r.headOption }\n      else { f.headOption }\n}\n\ndef last[R](dq: Dequeue[R]): Option[R] = dq match {\n    case Dequeue(f, fs, r, rs) =>\n      if ((fs == 1) && (rs == 0)) { f.headOption }\n      else { r.headOption }\n}\n\ndef check[R](dq: Dequeue[R]): Dequeue[R] = dq match {\n    case Dequeue(f, fs, r, rs) =>\n        val c = 4;\n        val size1 = (fs + rs) / 2;\n        val size2 = (fs + rs) - size1;\n\n        if (fs > c * rs + 1) {\n            val front = f.take(size1);\n            val rear = r.append(f.drop(size1).reverse);\n            Dequeue(front, size1, rear, size2)\n        } else if (rs > c * fs + 1) {\n            val front = f.append(r.drop(size1).reverse);\n            val rear = r.take(size1);\n            Dequeue(front, size2, rear, size1)\n        } else {\n            dq\n        }\n}\n\ndef pushFront[R](dq: Dequeue[R], el: R): Dequeue[R] = dq match {\n    case Dequeue(f, fs, r, rs) => Dequeue(Cons(el, f), fs + 1, r, rs).check\n}\n\ndef popFront[R](dq: Dequeue[R]): Option[(R, Dequeue[R])] = dq match {\n    case Dequeue(Nil(), fs, Cons(x, Nil()), rs) =>\n        Some((x, emptyQueue()))\n    case Dequeue(Nil(), fs, r, rs) =>\n        None()\n    case Dequeue(Cons(x, rest), fs, r, rs) =>\n        Some((x, Dequeue(rest, fs - 1, r, rs).check))\n}\n\ndef pushBack[R](dq: Dequeue[R], el: R): Dequeue[R] = dq match {\n    case Dequeue(f, fs, r, rs) => Dequeue(f, fs, Cons(el, r), rs + 1).check\n}\n\ndef popBack[R](dq: Dequeue[R]): Option[(R, Dequeue[R])] = dq match {\n    case Dequeue(Cons(x, Nil()), fs, Nil(), rs) =>\n        Some((x, emptyQueue()))\n    case Dequeue(f, fs, Nil(), rs) =>\n        None()\n    case Dequeue(f, fs, Cons(x, rest), rs) =>\n        Some((x, Dequeue(f, fs, rest, rs - 1).check))\n}\n\n// TODO: Replace when monomorphization is merged\n\n\ndef println(l: Dequeue[Int]): Unit = println(show(l))\ndef println(l: Dequeue[Double]): Unit = println(show(l))\ndef println(l: Dequeue[Bool]): Unit = println(show(l))\ndef println(l: Dequeue[String]): Unit = println(show(l))"),ef("common/effekt.effekt",'module effekt\n\nnamespace js {\n  // Runtime\n  extern include js "../js/effekt_runtime.js"\n\n  // Builtins\n  extern include js "../js/effekt_builtins.js"\n}\n\nnamespace chez {\n\n  // All Chez Scheme backends\n  // ------------------------\n  extern include chez "../chez/common/effekt_primitives.ss"\n\n  // call/cc based implementation\n  // ----------------------------\n  extern include chezCallCC "../chez/callcc/seq0.ss"\n  extern include chezCallCC "../chez/callcc/tail0.ss"\n  extern include chezCallCC "../chez/callcc/effekt.ss"\n\n  // CPS implementation\n  // ------------------\n  extern include chezCPS "../chez/cps/effekt.ss"\n\n  // Monadic implementation\n  // ----------------------\n  extern include chezMonadic "../chez/monadic/seq0.ss"\n  extern include chezMonadic "../chez/monadic/effekt.ss"\n}\n\nnamespace llvm {\n  extern include llvm "../llvm/rts.ll"\n  extern include llvm "../llvm/forward-declare-c.ll"\n}\n\n// Showing and debugging\n// =====================\n\nextern def print(value: String): Unit =\n  jsWeb "$effekt.println(${value})"\n  jsNode "$effekt.print(${value})"\n  chez "(print_impl ${value})"\n  llvm !!!MULTILINEMARKER!!!\n    call void @c_io_print(%Pos ${value})\n    ret %Pos zeroinitializer ; Unit\n  !!!MULTILINEMARKER!!!\n\nextern def println(value: String): Unit =\n  js "$effekt.println(${value})"\n  chez "(println_impl ${value})"\n  llvm !!!MULTILINEMARKER!!!\n    call void @c_io_println(%Pos ${value})\n    ret %Pos zeroinitializer ; Unit\n  !!!MULTILINEMARKER!!!\n\nextern jsNode !!!MULTILINEMARKER!!!\n$effekt.readln = function readln$impl(callback) {\n  const readline = require(\'node:readline\').createInterface({\n    input: process.stdin,\n    output: process.stdout,\n  });\n  readline.question(\'\', (answer) => {\n    readline.close();\n    callback(answer);\n  });\n}\n!!!MULTILINEMARKER!!!\n\nextern def readln() at async: String =\n  jsNode "$effekt.capture(callback => $effekt.readln(callback))"\n  llvm !!!MULTILINEMARKER!!!\n    %result = call %Pos @c_io_readln()\n    tail call void @resume_Pos(%Stack %stack, %Pos %result)\n    ret void\n  !!!MULTILINEMARKER!!!\n\ndef println(value: Int): Unit = println(value.show)\ndef println(value: Unit): Unit = println(value.show)\ndef println(value: Double): Unit = println(value.show)\ndef println(value: Bool): Unit = println(value.show)\ndef println(value: Byte): Unit = println(value.show)\ndef println(value: Char): Unit = println(value.show)\n\nextern def showBuiltin(value: Int) at {}: String =\n  js "\'\' + ${value}"\n  chez "(show-number ${value})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = call %Pos @c_bytearray_show_Int(%Int ${value})\n    ret %Pos %z\n  !!!MULTILINEMARKER!!!\n\nextern def showBuiltin(value: Double) at {}: String =\n  js "\'\' + ${value}"\n  chez "(show-number ${value})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = call %Pos @c_bytearray_show_Double(%Double ${value})\n    ret %Pos %z\n  !!!MULTILINEMARKER!!!\n\nextern def showBuiltin(value: Char) at {}: String =\n  js "String.fromCodePoint(${value})"\n  chez "(string (integer->char ${value}))"\n  llvm !!!MULTILINEMARKER!!!\n    %z = call %Pos @c_bytearray_show_Char(%Int ${value})\n    ret %Pos %z\n  !!!MULTILINEMARKER!!!\n\nextern def showBuiltin(value: Byte) at {}: String =\n  js "\'0x\' + ${value}.toString(16).toUpperCase().padStart(2, \'0\')"\n  chez "(format #f \\"0x~2,\'0X\\" ${value})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = call %Pos @c_bytearray_show_Byte(%Byte ${value})\n    ret %Pos %z\n  !!!MULTILINEMARKER!!!\n\nextern def inspect[R](value: R) at io: Unit =\n  default { println(show(value)) }\n\n/// A fatal runtime error that cannot be caught\nextern def panic(msg: String) at io: Nothing =\n  js "(function() { throw ${msg} })()"\n  chez "(raise ${msg})"\n  llvm !!!MULTILINEMARKER!!!\n    call void @c_io_println(%Pos ${msg})\n    call void @exit(i32 1)\n    ret %Pos zeroinitializer ; Unit\n  !!!MULTILINEMARKER!!!\n\n/// A show function structurally generated by the compiler for any type.\nextern def generated::show[R](value: R) at {}: String =\n  js "undefined"\n  chez "(void)"\n  llvm "ret %Pos poison"\n\n/// Returns a textual representation of a value for debugging purposes.\n/// The output is backend-specific, works only on JS and Chez backends.\n///\n/// Prefer using `show` instead when possible.\nextern def genericShow[R](value: R) at {}: String =\n  js "$effekt.show(${value})"\n  chez "(show_impl ${value})"\n\n// Strings\n// =======\nextern def infixPlusPlus(s1: String, s2: String) at {}: String =\n  js "${s1} + ${s2}"\n  chez "(string-append ${s1} ${s2})"\n  llvm !!!MULTILINEMARKER!!!\n    %spz = call %Pos @c_bytearray_concatenate(%Pos ${s1}, %Pos ${s2})\n    ret %Pos %spz\n  !!!MULTILINEMARKER!!!\n\n/// Beware that this function is backend-dependent.\n/// If you want to get the number of bytes that a string would take up in a UTF-8 encoding,\n/// use `string::utf8ByteLength` instead.\nextern def length(str: String) at {}: Int =\n  js "${str}.length"\n  chez "(string-length ${str})"\n  llvm !!!MULTILINEMARKER!!!\n    %x = call %Int @c_bytearray_size(%Pos ${str})\n    ret %Int %x\n  !!!MULTILINEMARKER!!!\n\nextern def unsafeSubstring(str: String, from: Int, to: Int) at {}: String =\n  js "${str}.substring(${from}, ${to})"\n  chez "(substring ${str} ${from} ${to})" // potentially raises: "Exception in substring: ..."\n  llvm !!!MULTILINEMARKER!!!\n    %x = call %Pos @c_bytearray_substring(%Pos ${str}, i64 ${from}, i64 ${to})\n    ret %Pos %x\n  !!!MULTILINEMARKER!!!\n\n\n// Side effecting ops\n// ==================\n\nextern def random() at io: Double =\n  js "Math.random()"\n  chez "(random 1.0)"\n  llvm !!!MULTILINEMARKER!!!\n    %r = call double @c_io_random()\n    ret double %r\n  !!!MULTILINEMARKER!!!\n\n// References and state\n// ====================\n// the following type is defined in builtins.scala\n// interface Ref[T] { def get(): T; def put(t: T): Unit }\n// extern io def freshIn[T](t: T) {r: Region}: Ref[T] at r = js "r.fresh(${t})"\n// extern io def freshGlobal[T](t: T): Ref[T] at global = js "$effekt.fresh(${t})"\n\n\n// Equality\n// ========\n\n/// Result of comparison between two objects according to some order:\n///\n/// - `Less()` means that the first object is *before* the first in the order,\n/// - `Equal()` means that the two objects are the same in the order,\n/// - and `Greater()` means that the second object is *before* the first in the order.\ntype Ordering {\n  Less();\n  Equal();\n  Greater()\n}\n\ndef compareInt(n: Int, m: Int) =\n  if (n == m) Equal()\n  else if (n < m) Less()\n  else Greater()\n\nextern def genericCompareImpl[R](x: R, y: R) at {}: Int =\n  js "$effekt.compare(${x}, ${y})"\n\n/// Compares two values of the same type, returning an `Ordering`.\n/// Only available on the JavaScript backend.\ndef genericCompare[R](x: R, y: R): Ordering = {\n  val ret = genericCompareImpl(x, y)\n  if (ret == 0) {\n    Equal()\n  } else if (ret < 0) {\n    Less()\n  } else { // ret > 0\n    Greater()\n  }\n}\n\ndef println(o: Ordering): Unit = println(o.show)\n\n\n// Comparison ops\n// ==============\n\n/// Structural equality: Not available in the LLVM backend\nextern def genericEquals[R](x: R, y: R) at {}: Bool =\n  js "$effekt.equals(${x}, ${y})"\n  chez "(equal_impl ${x} ${y})"\n\n// TODO fix this in the pattern matching compiler\nextern def infixEq(x: Unit, y: Unit) at {}: Bool =\n  default { true }\n\nextern def infixEq(x: Int, y: Int) at {}: Bool =\n  js "${x} === ${y}"\n  chez "(equal? ${x} ${y})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = icmp eq %Int ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixNeq(x: Int, y: Int) at {}: Bool =\n  js "${x} !== ${y}"\n  chez "(not (equal? ${x} ${y}))"\n  llvm !!!MULTILINEMARKER!!!\n    %z = icmp ne %Int ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixEq(x: Char, y: Char) at {}: Bool =\n  js "${x} === ${y}"\n  chez "(equal? ${x} ${y})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = icmp eq %Int ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixNeq(x: Char, y: Char) at {}: Bool =\n  js "${x} !== ${y}"\n  chez "(not (equal? ${x} ${y}))"\n  llvm !!!MULTILINEMARKER!!!\n    %z = icmp ne %Int ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixEq(x: String, y: String) at {}: Bool =\n  js "${x} === ${y}"\n  chez "(equal? ${x} ${y})"\n  llvm !!!MULTILINEMARKER!!!\n    %res = call %Pos @c_bytearray_equal(%Pos ${x}, %Pos ${y})\n    ret %Pos %res\n  !!!MULTILINEMARKER!!!\n\ndef infixNeq(x: String, y: String): Bool = not(x == y)\n\nextern def infixEq(x: Bool, y: Bool) at {}: Bool =\n  js "${x} === ${y}"\n  chez "(equal? ${x} ${y})"\n  llvm !!!MULTILINEMARKER!!!\n    %slim_x = extractvalue %Pos ${x}, 0\n    %slim_y = extractvalue %Pos ${y}, 0\n    %slim_z = icmp eq i64 %slim_x, %slim_y\n    %fat_z = zext i1 %slim_z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixNeq(x: Bool, y: Bool) at {}: Bool =\n  js "${x} !== ${y}"\n  chez "(not (equal? ${x} ${y}))"\n  llvm !!!MULTILINEMARKER!!!\n    %slim_x = extractvalue %Pos ${x}, 0\n    %slim_y = extractvalue %Pos ${y}, 0\n    %slim_z = icmp ne i64 %slim_x, %slim_y\n    %fat_z = zext i1 %slim_z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixEq(x: Byte, y: Byte) at {}: Bool =\n  js "${x} === ${y}"\n  chez "(equal? ${x} ${y})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = icmp eq %Byte ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixNeq(x: Byte, y: Byte) at {}: Bool =\n  js "${x} !== ${y}"\n  chez "(not (equal? ${x} ${y}))"\n  llvm !!!MULTILINEMARKER!!!\n    %z = icmp ne %Byte ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\n// Math ops\n// ========\nextern def infixPlus(x: Int, y: Int) at {}: Int =\n  js "(${x} + ${y})"\n  chez "(+ ${x} ${y})"\n  llvm "%z = add  %Int ${x}, ${y} ret %Int %z"\n\nextern def infixStar(x: Int, y: Int) at {}: Int =\n  js "(${x} * ${y})"\n  chez "(* ${x} ${y})"\n  llvm "%z = mul  %Int ${x}, ${y} ret %Int %z"\n\nextern def infixSlash(x: Int, y: Int) at {}: Int =\n  js "Math.floor(${x} / ${y})"\n  chez "(floor (/ ${x} ${y}))"\n  llvm "%z = sdiv %Int ${x}, ${y} ret %Int %z"\n\nextern def infixMinus(x: Int, y: Int) at {}: Int =\n  js "(${x} - ${y})"\n  chez "(- ${x} ${y})"\n  llvm "%z = sub  %Int ${x}, ${y} ret %Int %z"\n\nextern def mod(x: Int, y: Int) at {}: Int =\n  js "(${x} % ${y})"\n  chez "(modulo ${x} ${y})"\n  llvm "%z = srem %Int ${x}, ${y} ret %Int %z"\n\nextern def infixPlus(x: Double, y: Double) at {}: Double =\n  js "(${x} + ${y})"\n  chez "(+ ${x} ${y})"\n  llvm "%z = fadd %Double ${x}, ${y} ret %Double %z"\n\nextern def infixStar(x: Double, y: Double) at {}: Double =\n  js "(${x} * ${y})"\n  chez "(* ${x} ${y})"\n  llvm "%z = fmul %Double ${x}, ${y} ret %Double %z"\n\nextern def infixMinus(x: Double, y: Double) at {}: Double =\n  js "(${x} - ${y})"\n  chez "(- ${x} ${y})"\n  llvm "%z = fsub %Double ${x}, ${y} ret %Double %z"\n\nextern def infixSlash(x: Double, y: Double) at {}: Double =\n  js "(${x} / ${y})"\n  chez "(fl/ ${x} ${y})"\n  llvm "%z = fdiv %Double ${x}, ${y} ret %Double %z"\n\nextern def cos(x: Double) at {}: Double =\n  js "Math.cos(${x})"\n  chez "(cos ${x})"\n  llvm "%z = call %Double @llvm.cos.f64(double ${x}) ret %Double %z"\n\nextern def sin(x: Double) at {}: Double =\n  js "Math.sin(${x})"\n  chez "(sin ${x})"\n  llvm "%z = call %Double @llvm.sin.f64(double ${x}) ret %Double %z"\n\nextern def atan(x: Double) at {}: Double =\n  js "Math.atan(${x})"\n  chez "(atan ${x})"\n  llvm "%z = call %Double @atan(double ${x}) ret %Double %z"\n\nextern def tan(x: Double) at {}: Double =\n  js "Math.tan(${x})"\n  chez "(tan ${x})"\n  llvm "%z = call %Double @tan(double ${x}) ret %Double %z"\n\nextern def sqrt(x: Double) at {}: Double =\n  js "Math.sqrt(${x})"\n  chez "(sqrt ${x})"\n  llvm "%z = call %Double @llvm.sqrt.f64(double ${x}) ret %Double %z"\n\ndef square(x: Double): Double = x * x\n\ndef neg(n: Double): Double =\n  0.0 - n\n\ndef min(n: Double, m: Double): Double =\n  if (n < m) n else m\n\ndef max(n: Double, m: Double): Double =\n  if (n > m) n else m\n\ndef abs(n: Double): Double =\n  max(n, neg(n))\n\nextern def log(x: Double) at {}: Double =\n  js "Math.log(${x})"\n  chez "(log ${x})"\n  llvm "%z = call %Double @llvm.log.f64(double ${x}) ret %Double %z"\n\nextern def log1p(x: Double) at {}: Double =\n  js "Math.log1p(${x})"\n  chez "(log (+ ${x} 1))"\n  llvm "%z = call %Double @log1p(double ${x}) ret %Double %z"\n\nextern def exp(x: Double) at {}: Double =\n  js "Math.exp(${x})"\n  chez "(exp ${x})"\n  llvm "%z = call %Double @llvm.exp.f64(double ${x}) ret %Double %z"\n\ndef pow(base: Double, exponent: Int): Double = {\n  def loop(base: Double, exponent: Int, acc: Double): Double = {\n    if (exponent == 0) acc\n    else if (exponent.mod(2) == 0) loop(base * base, exponent / 2, acc)  // even exponent\n    else loop(base, exponent - 1, acc * base)  // odd exponent\n  }\n  if (exponent < 0) {\n    loop(1.0 / base, 0 - exponent, 1.0)\n  } else {\n    loop(base, exponent, 1.0)\n  }\n}\n\nextern def pow(base: Double, exponent: Double) at {}: Double =\n  js "Math.pow(${base}, ${exponent})"\n  chez "(expt ${base} ${exponent})"\n  llvm "%z = call %Double @llvm.pow.f64(double ${base}, double ${exponent}) ret %Double %z"\n\n// since we do not have "extern val", yet\nextern def _pi() at {}: Double =\n  js "Math.PI"\n  chez "(* 4 (atan 1))"\n  llvm "ret double 3.14159265358979323846264338327950288419716939937510582097494459"\n\nval PI: Double = _pi()\n\nextern def toInt(d: Double) at {}: Int =\n  js "Math.trunc(${d})"\n  chez "(flonum->fixnum ${d})"\n  llvm "%z = fptosi double ${d} to %Int ret %Int %z"\n\nextern def toDouble(d: Int) at {}: Double =\n  js "${d}"\n  chez "(fixnum->flonum ${d})"\n  llvm "%z = sitofp i64 ${d} to double ret double %z"\n\n\nextern def round(d: Double) at {}: Int =\n  js "Math.round(${d})"\n  chez "(flonum->fixnum (round ${d}))"\n  llvm !!!MULTILINEMARKER!!!\n    %i = call %Double @llvm.round.f64(double ${d})\n    %z = fptosi double %i to %Int ret %Int %z\n  !!!MULTILINEMARKER!!!\n\ndef round(d: Double, digits: Int): Double = {\n  val factor = pow(10.0, digits)\n  round(d * factor).toDouble / factor\n}\n\nextern def floor(d: Double) at {}: Int =\n  js "Math.floor(${d})"\n  chez "(flonum->fixnum (floor ${d}))"\n  llvm !!!MULTILINEMARKER!!!\n    %i = call %Double @llvm.floor.f64(double ${d})\n    %z = fptosi double %i to %Int ret %Int %z\n  !!!MULTILINEMARKER!!!\n\nextern def ceil(d: Double) at {}: Int =\n  js "Math.ceil(${d})"\n  chez "(flonum->fixnum (ceiling ${d}))"\n  llvm !!!MULTILINEMARKER!!!\n    %i = call %Double @llvm.ceil.f64(double ${d})\n    %z = fptosi double %i to %Int ret %Int %z\n  !!!MULTILINEMARKER!!!\n\ndef min(n: Int, m: Int): Int =\n  if (n < m) n else m\n\ndef max(n: Int, m: Int): Int =\n  if (n > m) n else m\n\ndef neg(n: Int): Int =\n    0 - n\n\ndef abs(n: Int): Int =\n    max(n, neg(n))\n\n\nextern def infixLt(x: Int, y: Int) at {}: Bool =\n  js "(${x} < ${y})"\n  chez "(< ${x} ${y})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = icmp slt %Int ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixLte(x: Int, y: Int) at {}: Bool =\n  js "(${x} <= ${y})"\n  chez "(<= ${x} ${y})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = icmp sle %Int ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixGt(x: Int, y: Int) at {}: Bool =\n  js "(${x} > ${y})"\n  chez "(> ${x} ${y})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = icmp sgt %Int ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixGte(x: Int, y: Int) at {}: Bool =\n  js "(${x} >= ${y})"\n  chez "(>= ${x} ${y})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = icmp sge %Int ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixEq(x: Double, y: Double) at {}: Bool =\n  js "${x} === ${y}"\n  chez "(= ${x} ${y})"\n\nextern def infixNeq(x: Double, y: Double) at {}: Bool =\n  js "${x} !== ${y}"\n  chez "(not (= ${x} ${y}))"\n\nextern def infixLt(x: Double, y: Double) at {}: Bool =\n  js "(${x} < ${y})"\n  chez "(< ${x} ${y})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = fcmp olt %Double ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixLte(x: Double, y: Double) at {}: Bool =\n  js "(${x} <= ${y})"\n  chez "(<= ${x} ${y})"\n\nextern def infixGt(x: Double, y: Double) at {}: Bool =\n  js "(${x} > ${y})"\n  chez "(> ${x} ${y})"\n  llvm !!!MULTILINEMARKER!!!\n    %z = fcmp ogt %Double ${x}, ${y}\n    %fat_z = zext i1 %z to i64\n    %adt_boolean = insertvalue %Pos zeroinitializer, i64 %fat_z, 0\n    ret %Pos %adt_boolean\n  !!!MULTILINEMARKER!!!\n\nextern def infixGte(x: Double, y: Double) at {}: Bool =\n  js "(${x} >= ${y})"\n  chez "(>= ${x} ${y})"\n\n// TODO do we really need those? if yes, move to string.effekt\nextern def infixLt(x: String, y: String) at {}: Bool =\n  js "(${x} < ${y})"\n  chez "(string<? ${x} ${y})"\n\nextern def infixLte(x: String, y: String) at {}: Bool =\n  js "(${x} <= ${y})"\n  chez "(string<=? ${x} ${y})"\n\nextern def infixGt(x: String, y: String) at {}: Bool =\n  js "(${x} > ${y})"\n  chez "(string>? ${x} ${y})"\n\nextern def infixGte(x: String, y: String) at {}: Bool =\n  js "(${x} >= ${y})"\n  chez "(string>=? ${x} ${y})"\n\n\n// Boolean operations\n// ==================\nextern def not(b: Bool) at {}: Bool =\n  js "!${b}"\n  chez "(not ${b})"\n  llvm !!!MULTILINEMARKER!!!\n    %p = extractvalue %Pos ${b}, 0\n    %q = xor i64 1, %p\n    %adt_q = insertvalue %Pos zeroinitializer, i64 %q, 0\n    ret %Pos %adt_q\n  !!!MULTILINEMARKER!!!\n\ndef infixBarBar { first: => Bool } { second: => Bool }: Bool =\n  if (first()) true else second()\n\ndef infixAmpAmp { first: => Bool } { second: => Bool }: Bool =\n  if (first()) second() else false\n\n\n// Bitwise operations\n// ==================\n\n/// Arithmetic left shift\nextern def bitwiseShl(x: Int, y: Int) at {}: Int =\n  js "(${x} << ${y})"\n  chez "(ash ${x} ${y})"\n  llvm "%z = shl %Int ${x}, ${y} ret %Int %z"\n\n/// Arithmetic right shift\nextern def bitwiseShr(x: Int, y: Int) at {}: Int =\n  js "(${x} >> ${y})"\n  chez "(ash ${x} (- ${y}))"\n  llvm "%z = ashr %Int ${x}, ${y} ret %Int %z"\n\nextern def bitwiseAnd(x: Int, y: Int) at {}: Int =\n  js "(${x} & ${y})"\n  chez "(logand ${x} ${y})"\n  llvm "%z = and %Int ${x}, ${y} ret %Int %z"\n\nextern def bitwiseOr(x: Int, y: Int) at {}: Int =\n  js "(${x} | ${y})"\n  chez "(logior ${x} ${y})"\n  llvm "%z = or %Int ${x}, ${y} ret %Int %z"\n\nextern def bitwiseXor(x: Int, y: Int) at {}: Int =\n  js "(${x} ^ ${y})"\n  chez "(logxor ${x} ${y})"\n  llvm "%z = xor %Int ${x}, ${y} ret %Int %z"\n\nextern def bitwiseNot(x: Int) at {}: Int =\n  js "(~${x})"\n  chez "(lognot ${x})"\n  llvm "%z = xor %Int ${x}, -1 ret %Int %z"\n\n\n// Byte operations\n// ===============\nextern def toByte(n: Int) at {}: Byte =\n  js "(${n} & 0xFF)"\n  llvm "%z = trunc %Int ${n} to %Byte ret %Byte %z"\n  chez "(logand ${n} 255)"\n\nextern def toInt(n: Byte) at {}: Int =\n  js "${n}"\n  llvm "%z = zext %Byte ${n} to %Int ret %Int %z"\n  chez "${n}"\n\n\n// Undefined and Null\n// ==================\n// Should only be used for interop with FFI, since values in Effekt\n// should not be undefined.\n//\n//   js:   undefined || null\n//   chez: #f\n//   llvm: null?\n\n/// The value used by the FFI to represent undefined values\nextern def undefined[A]() at {}: A =\n  js "undefined"\n  chez "#f"\n\n/// Is an FFI value undefined?\nextern def isUndefined[A](value: A) at {}: Bool =\n  js "(${value} === undefined || ${value} === null)"\n  chez "(eq? ${value} #f)"\n\n// Ascription\n// ==========\n\n/// Ascribe a type, for example `f().as[Int]`.\ndef as[A](x: A): A = x\n\n/// Witness absurdity, for example `f().absurd`.\n/// Very often the type argument is inferred.\ndef absurd[A](x: Nothing): A = x match {}\n\n// Tuples\n// ======\nrecord Tuple2[A, B](first: A, second: B)\nrecord Tuple3[A, B, C](first: A, second: B, third: C)\nrecord Tuple4[A, B, C, D](first: A, second: B, third: C, fourth: D)\nrecord Tuple5[A, B, C, D, E](first: A, second: B, third: C, fourth: D, fifth: E)\nrecord Tuple6[A, B, C, D, E, F](first: A, second: B, third: C, fourth: D, fifth: E, sixth: F)\n\n// OneOrBoth\n// =========\ntype OneOrBoth[A, B] {\n  This(a: A)\n  That(b: B)\n  Both(a: A, b: B)\n}\n\n// Control Flow\n// ============\n\n/// Repeat `action` forever\ndef forever { action: () => Unit }: Nothing = {\n  def go(): Nothing = { action(); go() }\n  go()\n}\n\n/// Signal that we should stop.\neffect stop(): Nothing\n\n/// When the program stops, then to here.\ndef boundary { program: () => Unit / stop }: Unit =\n  try { program() } with stop { () }\n\n/// Repeat `action` until `stop` is thrown.\ndef loop { acti